window.STORY_V23={"noe":[{"stage":"01 · EL CONTEXTO","name":"Noé","role":"El constructor del arca; el Génesis lo presenta como un hombre justo en un mundo violento.","mode":"historico","title":"Un mundo lleno de violencia","text":"La violencia y la corrupción se habían extendido, pero Noé procuraba andar con Dios en medio de aquel ambiente.","why":"El relato comienza mostrando por qué Jehová decidió intervenir y por qué Noé fue diferente.","reference":"Génesis 6:9–22; 7:1–16","index":0,"keyScene":true,"after":0},{"index":6,"after":0,"name":"Esposa de Noé","role":"Esposa de Noé; la Biblia no registra su nombre.","title":"Una voz importante del relato","text":"Apoyó a su familia durante los preparativos para el Diluvio y entró en el arca.","why":"El relato incluye a toda la familia, aunque no dé los nombres de las esposas.","reference":"Génesis 7:7,13","gender":"f","style":"older","mode":"historico","keyScene":false},{"stage":"02 · EL PRIMER CAMBIO","name":"Sem","role":"Uno de los tres hijos de Noé que entraron en el arca.","mode":"historico","title":"La orden de construir un arca","text":"Jehová explicó a Noé que llegaría un diluvio y le dio medidas e instrucciones para una embarcación enorme.","why":"Noé tuvo que actuar mucho antes de ver la lluvia; su obediencia fue práctica.","reference":"Génesis 6:9–22; 7:1–16","index":1,"keyScene":true,"after":1},{"index":7,"after":1,"name":"Cam","role":"Hijo de Noé.","title":"Una voz importante del relato","text":"Cam fue uno de los tres hijos que entraron en el arca con sus esposas.","why":"La salvación de la familia implicó actuar unida y obedecer.","reference":"Génesis 7:13","gender":"m","style":"young","mode":"historico","keyScene":false},{"stage":"03 · EL DESAFÍO","name":"Esposa de Noé","role":"Esposa de Noé; nombre no registrado.","mode":"historico","title":"Un trabajo de familia","text":"Noé preparó el arca con su familia y reunió los alimentos y lo necesario para sobrevivir.","why":"La tarea exigía perseverancia y cooperación durante un período prolongado.","reference":"Génesis 6:9–22; 7:1–16","index":2,"keyScene":true,"after":2},{"index":8,"after":2,"name":"Esposa de Sem","role":"Nuera de Noé; nombre no registrado.","title":"Una voz importante del relato","text":"Entró en el arca junto a Sem y los otros familiares.","why":"El registro no presenta a los familiares como personas aisladas.","reference":"Génesis 7:13","gender":"f","style":"young","mode":"historico","keyScene":false},{"stage":"04 · LA RESPUESTA","name":"Jafet","role":"Hijo de Noé que estuvo junto a su familia durante el Diluvio.","mode":"historico","title":"La entrada en el arca","text":"Noé entró en el arca con su esposa, sus tres hijos y sus nueras. También entraron animales según las instrucciones recibidas.","why":"La familia no esperó a que comenzara el desastre para ponerse a salvo.","reference":"Génesis 6:9–22; 7:1–16","index":3,"keyScene":true,"after":3},{"index":9,"after":3,"name":"Esposa de Jafet","role":"Nuera de Noé; nombre no registrado.","title":"Una voz importante del relato","text":"Fue una de las ocho personas protegidas en el arca.","why":"Una historia colectiva puede incluir personas cuyo nombre no se conservó.","reference":"1 Pedro 3:20","gender":"f","style":"adult","mode":"historico","keyScene":false},{"stage":"05 · EL PUNTO DECISIVO","name":"Cam","role":"Hijo de Noé y sobreviviente del Diluvio.","mode":"historico","title":"El Diluvio","text":"Comenzó a llover y las aguas aumentaron; quienes estaban dentro del arca quedaron protegidos mientras la Tierra era inundada.","why":"La diferencia entre escuchar una advertencia y actuar fue decisiva.","reference":"Génesis 6:9–22; 7:1–16","index":4,"keyScene":true,"after":4},{"index":10,"after":4,"name":"Familia de Noé","role":"Grupo familiar; intervención colectiva.","title":"Una voz importante del relato","text":"Después de que cesó la lluvia, esperaron a que fuera seguro salir del arca.","why":"Esperar las indicaciones fue parte de la obediencia.","reference":"Génesis 8:13-19","gender":"g","style":"group","mode":"historico","keyScene":false},{"stage":"06 · LAS CONSECUENCIAS","name":"Noé","role":"El constructor del arca; el Génesis lo presenta como un hombre justo en un mundo violento.","mode":"historico","title":"Un nuevo comienzo","text":"Después de que bajaron las aguas, Noé y su familia salieron del arca. Jehová estableció un pacto relacionado con el arcoíris.","why":"La historia termina con un nuevo comienzo y la promesa de que no habría otro diluvio mundial.","reference":"Génesis 6:9–22; 7:1–16","index":5,"keyScene":true,"after":5}],"abrahan":[{"stage":"01 · EL CONTEXTO","name":"Abrahán","role":"Patriarca que salió de Ur por fe y recibió promesas de Jehová.","mode":"historico","title":"La vida en Ur","text":"Abrahán y Sara vivían en Ur, una ciudad importante de Mesopotamia. Dejar ese entorno suponía despedirse de una forma de vida establecida.","why":"Su fe no comenzó con una respuesta a todas sus preguntas, sino con disposición a escuchar.","reference":"Génesis 12:1–9","index":0,"keyScene":true,"after":0},{"index":6,"after":0,"name":"Sara","role":"Esposa de Abrahán, antes llamada Sarai.","title":"Una voz importante del relato","text":"Salió de Ur con su familia y aceptó vivir como extranjera.","why":"Su fe acompañó las decisiones de Abrahán, aunque el cambio afectó su propia vida.","reference":"Génesis 11:29-31; Hebreos 11:11","gender":"f","style":"adult","mode":"historico","keyScene":false},{"stage":"02 · EL PRIMER CAMBIO","name":"Taré","role":"Padre de Abrahán, que salió con la familia de Ur hacia Harán.","mode":"historico","title":"Viaje hasta Harán","text":"La familia salió de Ur y se estableció por un tiempo en Harán; Taré, el padre de Abrahán, formó parte de esa etapa del recorrido.","why":"El viaje tuvo etapas, no fue un único traslado instantáneo.","reference":"Génesis 12:1–9","index":1,"keyScene":true,"after":1},{"stage":"03 · EL DESAFÍO","name":"Sara","role":"Esposa de Abrahán, que compartió sus viajes y desafíos.","mode":"historico","title":"Una promesa para el futuro","text":"Jehová le dijo a Abrahán que saliera hacia la tierra que le mostraría y le prometió bendiciones relacionadas con su descendencia.","why":"Abrahán recibió dirección y promesas, aunque todavía no conocía todos los detalles.","reference":"Génesis 12:1–9","index":2,"keyScene":true,"after":2},{"stage":"04 · LA RESPUESTA","name":"Lot","role":"Sobrino de Abrahán, quien viajó con él hacia Canaán.","mode":"historico","title":"Entrada en Canaán","text":"Abrahán salió de Harán acompañado por Sara y Lot, y llegó a la tierra de Canaán. Allí siguió viviendo como residente extranjero.","why":"La confianza se manifestó en decisiones concretas, como abandonar un lugar conocido.","reference":"Génesis 12:1–9","index":3,"keyScene":true,"after":3},{"index":7,"after":3,"name":"Lot","role":"Sobrino de Abrahán.","title":"Una voz importante del relato","text":"Viajó con Abrahán y salió con él de Harán hacia Canaán.","why":"La obediencia de Abrahán afectó también a personas de su familia.","reference":"Génesis 12:4-5","gender":"m","style":"young","mode":"historico","keyScene":false},{"stage":"05 · EL PUNTO DECISIVO","name":"Sara","role":"Esposa de Abrahán; recorrió Canaán con él.","mode":"historico","title":"Altares y adoración","text":"En Canaán, Abrahán construyó altares e invocó el nombre de Jehová en lugares como Siquem y Betel.","why":"La adoración siguió siendo central durante sus desplazamientos.","reference":"Génesis 12:1–9","index":4,"keyScene":true,"after":4},{"stage":"06 · LAS CONSECUENCIAS","name":"Sara","role":"Esposa de Abrahán, que compartió sus viajes y desafíos.","mode":"historico","title":"Una vida de fe perseverante","text":"Abrahán y Sara continuaron viviendo en tiendas mientras aguardaban el cumplimiento de las promesas divinas.","why":"La fe de Abrahán se ve en un camino largo, no solo en un primer paso valiente.","reference":"Génesis 12:1–9","index":5,"keyScene":true,"after":5},{"index":8,"after":5,"name":"Eliezer de Damasco","role":"Siervo de confianza vinculado a la casa de Abrahán.","title":"Una voz importante del relato","text":"Abrahán lo mencionó más tarde al preguntar por el futuro de su casa.","why":"Su presencia ayuda a comprender el tamaño y organización de aquel hogar.","reference":"Génesis 15:2-3","gender":"m","style":"adult","mode":"historico","keyScene":false},{"index":9,"after":5,"name":"Isaac","role":"Hijo de Abrahán y Sara.","title":"Una voz importante del relato","text":"Nació cuando sus padres eran mayores, tal como se les había prometido.","why":"Su nacimiento está conectado con la promesa de una descendencia.","reference":"Génesis 21:1-7","gender":"m","style":"child","mode":"historico","keyScene":false},{"index":10,"after":5,"name":"Ismael","role":"Hijo de Abrahán y Agar.","title":"Una voz importante del relato","text":"Formó parte de la familia de Abrahán antes del nacimiento de Isaac.","why":"Conocerlo permite entender las relaciones familiares y las decisiones posteriores.","reference":"Génesis 16:15-16; 21:8-21","gender":"m","style":"young","mode":"historico","keyScene":false},{"index":11,"after":5,"name":"Agar","role":"Sierva egipcia y madre de Ismael.","title":"Una voz importante del relato","text":"En medio de sus dificultades recibió ayuda y dirección en el desierto.","why":"Su historia amplía la mirada a otros integrantes del hogar.","reference":"Génesis 16:1-16; 21:14-21","gender":"f","style":"adult","mode":"historico","keyScene":false}],"jose":[{"stage":"01 · EL CONTEXTO","name":"José","role":"Hijo de Jacob; vendido como esclavo por sus hermanos.","mode":"historico","title":"Una juventud marcada por los celos","text":"José recibió de su padre una túnica especial y contó sueños que provocaron la envidia de sus hermanos. Fue vendido y llevado a Egipto.","why":"Así se entiende por qué un joven israelita terminó trabajando lejos de su familia.","reference":"Génesis 37:3-36","index":0,"keyScene":true,"after":0},{"index":6,"after":0,"name":"Jacob","role":"Padre de José y de sus hermanos.","title":"Una voz importante del relato","text":"Jacob mostró especial afecto por José, y sus hermanos notaron esa preferencia.","why":"La tensión familiar explica por qué la relación terminó siendo tan conflictiva.","reference":"Génesis 37:3-4","gender":"m","style":"older","mode":"historico","keyScene":false},{"index":7,"after":0,"name":"Rubén","role":"Hermano mayor de José.","title":"Una voz importante del relato","text":"Rubén intentó impedir que sus hermanos mataran a José y propuso ponerlo en una cisterna.","why":"No todos los hermanos reaccionaron igual ante los celos.","reference":"Génesis 37:21-22","gender":"m","style":"adult","mode":"historico","keyScene":false},{"index":8,"after":0,"name":"Judá","role":"Uno de los hermanos de José.","title":"Una voz importante del relato","text":"Judá propuso vender a José a una caravana en vez de derramar su sangre.","why":"Su participación explica el traslado de José a Egipto.","reference":"Génesis 37:26-28","gender":"m","style":"adult","mode":"historico","keyScene":false},{"stage":"02 · EL PRIMER CAMBIO","name":"José","role":"Siervo fiel en la casa de Potifar.","mode":"historico","title":"La tentación y la acusación","text":"En Egipto, José ganó la confianza de Potifar. Rechazó las propuestas de su esposa y terminó encarcelado tras una acusación falsa.","why":"Hizo lo correcto aunque eso le causó sufrimiento.","reference":"Génesis 39:1-23","index":1,"keyScene":true,"after":1},{"index":9,"after":1,"name":"Potifar","role":"Funcionario egipcio que compró a José.","title":"Una voz importante del relato","text":"Observó el trabajo de José y le confió la administración de su casa.","why":"José demostró responsabilidad incluso viviendo como esclavo.","reference":"Génesis 39:1-6","gender":"m","style":"adult","mode":"historico","keyScene":false},{"index":10,"after":1,"name":"Esposa de Potifar","role":"Esposa del amo de José; la Biblia no registra su nombre.","title":"Una voz importante del relato","text":"Insistió en que José se acostara con ella; cuando él huyó, lo acusó falsamente.","why":"La fidelidad de José fue puesta a prueba y sufrió una injusticia por hacer lo correcto.","reference":"Génesis 39:7-20","gender":"f","style":"adult","mode":"historico","keyScene":false},{"stage":"03 · EL DESAFÍO","name":"José","role":"Prisionero que interpretó los sueños de sus compañeros.","mode":"historico","title":"Los sueños en la prisión","text":"José interpretó los sueños del copero y del panadero del faraón. Los acontecimientos sucedieron como había dicho, pero el copero lo olvidó durante un tiempo.","why":"Este período muestra paciencia y capacidad de ayudar incluso en la cárcel.","reference":"Génesis 40:1-23","index":2,"keyScene":true,"after":2},{"index":11,"after":2,"name":"Encargado de la prisión","role":"Funcionario responsable de los presos, sin nombre registrado.","title":"Una voz importante del relato","text":"Llegó a confiar en José y le encargó tareas dentro de la prisión.","why":"La conducta de José continuó siendo ejemplar en circunstancias injustas.","reference":"Génesis 39:21-23","gender":"m","style":"older","mode":"historico","keyScene":false},{"index":12,"after":2,"name":"Copero principal","role":"Funcionario que servía las bebidas al faraón.","title":"Una voz importante del relato","text":"Soñó con una vid y escuchó de José que recuperaría su cargo; luego se olvidó de mencionarlo.","why":"Su recuerdo posterior permitió que José fuera llamado ante el faraón.","reference":"Génesis 40:9-23; 41:9-14","gender":"m","style":"adult","mode":"historico","keyScene":false},{"index":13,"after":2,"name":"Panadero principal","role":"Funcionario de la casa real encarcelado con el copero.","title":"Una voz importante del relato","text":"Contó a José un sueño sobre canastas de pan; la interpretación anunciaba un desenlace triste.","why":"Los dos sueños se cumplieron como José había explicado.","reference":"Génesis 40:16-22","gender":"m","style":"adult","mode":"historico","keyScene":false},{"stage":"04 · LA RESPUESTA","name":"José","role":"Intérprete de los sueños reales y administrador de Egipto.","mode":"historico","title":"Del calabozo al palacio","text":"El faraón soñó con siete años de abundancia y siete de hambre. José explicó los sueños y recomendó almacenar reservas. El faraón le encargó la tarea.","why":"La previsión de José permitió que hubiera alimento durante la escasez.","reference":"Génesis 41:1-57","index":3,"keyScene":true,"after":3},{"index":14,"after":3,"name":"Faraón","role":"Gobernante egipcio en la época de José.","title":"Una voz importante del relato","text":"Soñó con siete vacas gordas y siete flacas; llamó a José para que interpretara los sueños.","why":"Su decisión de confiar autoridad a José permitió preparar reservas para el hambre.","reference":"Génesis 41:1-44","gender":"m","style":"older","mode":"historico","keyScene":false},{"stage":"05 · EL PUNTO DECISIVO","name":"Judá","role":"Uno de los hermanos de José.","mode":"historico","title":"Regreso a Egipto durante el hambre","text":"Los hermanos de José llegaron a Egipto en busca de alimento. José los reconoció, puso a prueba sus intenciones y exigió ver a Benjamín.","why":"El encuentro revelaría si habían cambiado después de tratar cruelmente a José.","reference":"Génesis 42:1-38; 43:1-34","index":4,"keyScene":true,"after":4},{"index":15,"after":4,"name":"Benjamín","role":"Hermano menor de José.","title":"Una voz importante del relato","text":"Años después viajó con sus hermanos a Egipto; José quería comprobar cómo lo tratarían.","why":"Su presencia fue decisiva para poner a prueba el cambio de actitud de la familia.","reference":"Génesis 42:4; 43:29; 44:12-34","gender":"m","style":"young","mode":"historico","keyScene":false},{"index":16,"after":4,"name":"Simeón","role":"Hermano de José.","title":"Una voz importante del relato","text":"José lo mantuvo retenido hasta que sus hermanos regresaron con Benjamín.","why":"La familia debió regresar y afrontar las consecuencias de sus decisiones.","reference":"Génesis 42:24; 43:23","gender":"m","style":"adult","mode":"historico","keyScene":false},{"index":17,"after":4,"name":"Judá, el hermano que respondió","role":"Hermano de José que habló en nombre de la familia.","title":"Una voz importante del relato","text":"Se ofreció a quedarse como esclavo para que Benjamín volviera con su padre.","why":"Su disposición al sacrificio mostró una transformación respecto al pasado.","reference":"Génesis 44:18-34","gender":"m","style":"adult","mode":"historico","keyScene":false},{"stage":"06 · LAS CONSECUENCIAS","name":"José","role":"Hermano que decidió perdonar y reunirse con su familia.","mode":"historico","title":"Perdón y reencuentro","text":"Judá se ofreció a quedarse por Benjamín; José reveló quién era, lloró con sus hermanos y la familia terminó reuniéndose en Egipto.","why":"El desenlace muestra la posibilidad de reparar vínculos después de una injusticia grave.","reference":"Génesis 44:18-34; 45:1-15; 46:28-30","index":5,"keyScene":true,"after":5},{"index":18,"after":5,"name":"Jacob, al final del viaje","role":"Padre de los hermanos.","title":"Una voz importante del relato","text":"Al saber que José vivía, viajó a Egipto y pudo volver a verlo.","why":"La historia concluye con una reunión familiar después de años de separación.","reference":"Génesis 45:25-28; 46:28-30","gender":"m","style":"older","mode":"historico","keyScene":false}],"moises":[{"stage":"01 · EL CONTEXTO","name":"Moisés","role":"Líder de Israel durante la salida de Egipto.","mode":"historico","title":"Una infancia bajo amenaza","text":"En Egipto, la madre y la hermana de Moisés lo protegieron cuando el faraón ordenó matar a los niños israelitas.","why":"Su supervivencia estuvo ligada al valor y a la iniciativa de su familia.","reference":"Éxodo 1:22; 2:1-10","index":0,"keyScene":true,"after":0},{"index":6,"after":0,"name":"Jokébed","role":"Madre de Moisés.","title":"Una voz importante del relato","text":"Lo escondió durante tres meses para protegerlo de la orden del faraón.","why":"La historia de Moisés comienza con la valentía de su familia.","reference":"Éxodo 2:1-3","gender":"f","style":"adult","mode":"historico","keyScene":false},{"index":7,"after":0,"name":"Míriam, hermana de Moisés","role":"Hermana mayor de Moisés.","title":"Una voz importante del relato","text":"Vigiló la cesta y habló con la hija del faraón para conseguir una nodriza.","why":"Su iniciativa ayudó a preservar la vida de su hermano.","reference":"Éxodo 2:4-8","gender":"f","style":"young","mode":"historico","keyScene":false},{"stage":"02 · EL PRIMER CAMBIO","name":"Moisés","role":"Hermano de Moisés que lo ayudó a hablar ante el pueblo y el faraón.","mode":"historico","title":"Criado en Egipto y una decisión de fe","text":"Moisés creció con acceso a la corte egipcia, pero más tarde escogió identificarse con el pueblo de Israel.","why":"La decisión muestra que su fe pesó más que los privilegios de la corte.","reference":"Éxodo 2:10-15; Hebreos 11:24-26","index":1,"keyScene":true,"after":1},{"index":8,"after":1,"name":"Hija del faraón","role":"Princesa egipcia que encontró a Moisés.","title":"Una voz importante del relato","text":"Tuvo compasión del niño y lo adoptó.","why":"Su actuación dio a Moisés una educación muy diferente a la de otros hebreos.","reference":"Éxodo 2:5-10","gender":"f","style":"adult","mode":"historico","keyScene":false},{"index":9,"after":1,"name":"Aarón","role":"Hermano de Moisés y su portavoz.","title":"Una voz importante del relato","text":"Acompañó a Moisés ante el faraón para exigir la liberación de Israel.","why":"Mostró que Moisés no cumplió su encargo solo.","reference":"Éxodo 4:14-16; 7:1-2","gender":"m","style":"older","mode":"historico","keyScene":false},{"stage":"03 · EL DESAFÍO","name":"Aarón","role":"Hermana de Moisés y profetisa del pueblo israelita.","mode":"historico","title":"El encargo de liberar a Israel","text":"Moisés volvió a Egipto con Aarón y hablaron al faraón. Como este se resistió, tuvieron lugar las plagas.","why":"La liberación no dependió de la autoridad de Moisés, sino de Jehová.","reference":"Éxodo 4:27-31; 7-12","index":2,"keyScene":true,"after":2},{"index":10,"after":2,"name":"Faraón de Egipto","role":"Rey que resistió la petición de dejar marchar a los israelitas.","title":"Una voz importante del relato","text":"Endureció su postura a pesar de las plagas y más tarde envió carros tras el pueblo.","why":"Su oposición fue la causa inmediata de la persecución junto al mar Rojo.","reference":"Éxodo 5:1-2; 14:5-9","gender":"m","style":"older","mode":"historico","keyScene":false},{"stage":"04 · LA RESPUESTA","name":"Moisés","role":"Líder de Israel a orillas del mar Rojo.","mode":"historico","title":"Del éxodo a las orillas del mar Rojo","text":"Los israelitas salieron de Egipto, pero pronto vieron acercarse al ejército del faraón y sintieron miedo.","why":"Ese momento puso a prueba su confianza y mostró la importancia del liderazgo.","reference":"Éxodo 12:31-42; 14:5-14","index":3,"keyScene":true,"after":3},{"index":11,"after":3,"name":"Pueblo de Israel","role":"Grupo de familias israelitas.","title":"Una voz importante del relato","text":"Temieron cuando vieron al ejército egipcio cerca del mar.","why":"El momento pone de relieve su temor y la dirección de Moisés.","reference":"Éxodo 14:10-14","gender":"g","style":"group","mode":"historico","keyScene":false},{"stage":"05 · EL PUNTO DECISIVO","name":"Moisés","role":"Líder de Israel durante la salida de Egipto.","mode":"historico","title":"El camino a través del mar","text":"Jehová hizo que el mar se separara y los israelitas cruzaron por terreno seco.","why":"La liberación quedó presentada como un acontecimiento decisivo en la historia de Israel.","reference":"Éxodo 14:15-29","index":4,"keyScene":true,"after":4},{"stage":"06 · LAS CONSECUENCIAS","name":"Míriam","role":"Hermana de Moisés y profetisa del pueblo israelita.","mode":"historico","title":"Un cántico después de cruzar","text":"Israel llegó a salvo al otro lado, y Míriam dirigió a las mujeres en un cántico de agradecimiento.","why":"El desenlace de la historia une liberación y gratitud.","reference":"Éxodo 15:1-21","index":5,"keyScene":true,"after":5},{"index":12,"after":5,"name":"Míriam y las mujeres","role":"Grupo guiado por Míriam.","title":"Una voz importante del relato","text":"Después de cruzar el mar, cantaron en agradecimiento por la liberación.","why":"El relato culmina con una respuesta de gratitud.","reference":"Éxodo 15:20-21","gender":"f","style":"older","mode":"historico","keyScene":false}],"rahab":[{"stage":"01 · EL CONTEXTO","name":"Rahab","role":"Mujer de Jericó que dio refugio a mensajeros israelitas.","mode":"historico","title":"Una mujer en Jericó","text":"Rahab vivía en Jericó, una ciudad que iba a verse afectada por la entrada de Israel en Canaán.","why":"Su decisión se tomó cuando el futuro de su ciudad era incierto.","reference":"Josué 2:1–21; 6:22–25","index":0,"keyScene":true,"after":0},{"index":6,"after":0,"name":"Rey de Jericó","role":"Gobernante de la ciudad; nombre no registrado.","title":"Una voz importante del relato","text":"Se enteró de que habían entrado espías israelitas y ordenó buscarlos.","why":"Representa el peligro que corrieron Rahab y los visitantes.","reference":"Josué 2:2-3","gender":"m","style":"older","mode":"historico","keyScene":false},{"stage":"02 · EL PRIMER CAMBIO","name":"Dos espías israelitas","role":"Enviados por Josué; sus nombres no se mencionan.","mode":"historico","title":"Llegan dos espías","text":"Dos mensajeros israelitas llegaron a la ciudad para examinar la situación. Rahab les dio alojamiento y los escondió.","why":"Ayudarlos implicaba un riesgo personal.","reference":"Josué 2:1–21; 6:22–25","index":1,"keyScene":true,"after":1},{"index":7,"after":1,"name":"Primer espía","role":"Enviado israelita; su nombre no se conserva.","title":"Una voz importante del relato","text":"Entró con su compañero en Jericó para reconocer la ciudad.","why":"La misión preparó la entrada de los israelitas en Canaán.","reference":"Josué 2:1","gender":"m","style":"adult","mode":"historico","keyScene":false},{"index":8,"after":1,"name":"Segundo espía","role":"Compañero del primer espía; sin nombre registrado.","title":"Una voz importante del relato","text":"Rahab lo escondió junto al otro mensajero y luego los ayudó a escapar.","why":"Rahab actuó a favor de quienes reconocía como siervos de Jehová.","reference":"Josué 2:4-16","gender":"m","style":"young","mode":"historico","keyScene":false},{"stage":"03 · EL DESAFÍO","name":"Rahab","role":"Mujer de Jericó que dio refugio a mensajeros israelitas.","mode":"historico","title":"Por qué decidió ayudarlos","text":"Rahab había oído lo que Jehová había hecho por Israel y expresó que reconocía su poder.","why":"Su manera de actuar estuvo relacionada con lo que había aprendido.","reference":"Josué 2:1–21; 6:22–25","index":2,"keyScene":true,"after":2},{"stage":"04 · LA RESPUESTA","name":"Familia de Rahab","role":"Padres y familiares por quienes Rahab pidió protección.","mode":"historico","title":"Una petición por su familia","text":"Rahab pidió protección para su padre, su madre y los demás miembros de su familia. Los mensajeros le dieron instrucciones para identificarlos.","why":"Pensó también en la seguridad de sus seres queridos.","reference":"Josué 2:1–21; 6:22–25","index":3,"keyScene":true,"after":3},{"index":9,"after":3,"name":"Padre de Rahab","role":"Padre de Rahab; nombre no registrado.","title":"Una voz importante del relato","text":"Rahab pidió que él y toda su familia fueran protegidos.","why":"Su petición mostró preocupación por la vida de sus familiares.","reference":"Josué 2:12-13","gender":"m","style":"older","mode":"historico","keyScene":false},{"stage":"05 · EL PUNTO DECISIVO","name":"Rahab","role":"Mujer de Jericó que dio refugio a mensajeros israelitas.","mode":"historico","title":"La cuerda escarlata","text":"Rahab debía colocar una cuerda roja en su ventana y reunir a su familia en su casa.","why":"La señal tenía que ir acompañada de seguir las instrucciones.","reference":"Josué 2:1–21; 6:22–25","index":4,"keyScene":true,"after":4},{"index":10,"after":4,"name":"Josué","role":"Dirigente de Israel después de Moisés.","title":"Una voz importante del relato","text":"Ordenó a los espías que rescataran a Rahab y a quienes estaban con ella.","why":"La promesa de protección fue cumplida cuando cayó Jericó.","reference":"Josué 6:22-25","gender":"m","style":"older","mode":"historico","keyScene":false},{"stage":"06 · LAS CONSECUENCIAS","name":"Rahab","role":"Mujer de Jericó que dio refugio a mensajeros israelitas.","mode":"historico","title":"Una familia rescatada","text":"Cuando Jericó fue conquistada, Rahab y quienes estaban con ella en la casa fueron librados.","why":"El desenlace conecta fe, valor y acciones concretas.","reference":"Josué 2:1–21; 6:22–25","index":5,"keyScene":true,"after":5}],"rut":[{"stage":"01 · EL CONTEXTO","name":"Noemí","role":"Israelita viuda que regresó de Moab a Belén.","mode":"historico","title":"Pérdidas en Moab","text":"Noemí había perdido a su esposo y a sus dos hijos. Sus nueras Rut y Orpá también habían enviudado.","why":"La historia comienza en un momento de dolor e incertidumbre.","reference":"Rut 1:16–22; 2:1–17","index":0,"keyScene":true,"after":0},{"index":6,"after":0,"name":"Elimélec","role":"Esposo de Noemí.","title":"Una voz importante del relato","text":"Se trasladó con su familia de Belén a Moab durante una escasez de alimentos.","why":"Su muerte fue una de las pérdidas que cambiaron la vida de Noemí.","reference":"Rut 1:1-3","gender":"m","style":"older","mode":"historico","keyScene":false},{"stage":"02 · EL PRIMER CAMBIO","name":"Noemí","role":"Israelita viuda que regresó de Moab a Belén.","mode":"historico","title":"La decisión de volver","text":"Noemí se enteró de que había alimento en Judá y decidió regresar desde Moab a Belén.","why":"Volver significaba empezar de nuevo con muy pocos recursos.","reference":"Rut 1:16–22; 2:1–17","index":1,"keyScene":true,"after":1},{"index":7,"after":1,"name":"Orpá","role":"Nuera de Noemí y cuñada de Rut.","title":"Una voz importante del relato","text":"Después de despedirse de Noemí regresó a su pueblo.","why":"Su elección contrasta con la decisión de Rut de quedarse con Noemí.","reference":"Rut 1:8-15","gender":"f","style":"young","mode":"historico","keyScene":false},{"stage":"03 · EL DESAFÍO","name":"Rut","role":"Moabita que eligió acompañar lealmente a Noemí.","mode":"historico","title":"Rut decide acompañarla","text":"Aunque Noemí le ofreció volver con los suyos, Rut eligió quedarse a su lado y adorar a su Dios.","why":"La lealtad de Rut no fue solo una emoción: cambió su futuro.","reference":"Rut 1:16–22; 2:1–17","index":2,"keyScene":true,"after":2},{"stage":"04 · LA RESPUESTA","name":"Noemí","role":"Suegra de Rut; regresó con ella a Belén.","mode":"historico","title":"Llegada a Belén","text":"Rut y Noemí llegaron a Belén al comienzo de la cosecha de cebada.","why":"Ese momento abrió una oportunidad práctica de conseguir alimento.","reference":"Rut 1:16–22; 2:1–17","index":3,"keyScene":true,"after":3},{"index":8,"after":3,"name":"Segadores de Boaz","role":"Trabajadores del campo donde Rut recogió espigas.","title":"Una voz importante del relato","text":"Dejaron que Rut recogiera alimento durante la cosecha, según las indicaciones de Boaz.","why":"El trabajo cotidiano se convirtió en ocasión de bondad hacia una extranjera.","reference":"Rut 2:4-16","gender":"g","style":"group","mode":"historico","keyScene":false},{"stage":"05 · EL PUNTO DECISIVO","name":"Boaz","role":"Propietario israelita que mostró bondad a Rut y Noemí.","mode":"historico","title":"En el campo de Boaz","text":"Rut recogió espigas detrás de los segadores en un campo de Boaz, quien se interesó por su bienestar.","why":"La bondad y la generosidad aparecen junto con el trabajo diligente.","reference":"Rut 1:16–22; 2:1–17","index":4,"keyScene":true,"after":4},{"index":9,"after":4,"name":"Boaz","role":"Propietario de tierras y pariente de Elimélec.","title":"Una voz importante del relato","text":"Protegió a Rut, le permitió recoger alimento y reconoció su lealtad.","why":"Su bondad contribuyó al bienestar de las dos viudas.","reference":"Rut 2:8-12","gender":"m","style":"older","mode":"historico","keyScene":false},{"index":10,"after":4,"name":"Pariente con prioridad de rescate","role":"Pariente más cercano, cuyo nombre no se registra.","title":"Una voz importante del relato","text":"No aceptó ejercer el derecho de rescate que correspondía primero a él.","why":"Su decisión abrió la vía legal para que Boaz actuara.","reference":"Rut 4:1-10","gender":"m","style":"older","mode":"historico","keyScene":false},{"stage":"06 · LAS CONSECUENCIAS","name":"Rut","role":"Moabita que eligió acompañar lealmente a Noemí.","mode":"historico","title":"Una familia y una esperanza","text":"Boaz se casó con Rut; con el tiempo, su familia quedó vinculada al linaje del rey David.","why":"Una historia de pérdidas terminó dando lugar a una nueva etapa familiar.","reference":"Rut 1:16–22; 2:1–17","index":5,"keyScene":true,"after":5}],"samuel":[{"stage":"01 · EL CONTEXTO","name":"Samuel","role":"Joven que servía en el tabernáculo y llegó a ser profeta.","mode":"historico","title":"Un niño en el tabernáculo","text":"Samuel servía a Jehová en el tabernáculo bajo la supervisión del sacerdote Elí.","why":"Era joven, pero ya participaba en labores de servicio.","reference":"1 Samuel 3:1–10","index":0,"keyScene":true,"after":0},{"index":6,"after":0,"name":"Ana","role":"Madre de Samuel.","title":"Una voz importante del relato","text":"Oró por un hijo y prometió dedicarlo al servicio de Jehová.","why":"La historia de Samuel comienza con la fe y gratitud de su madre.","reference":"1 Samuel 1:10-11,20,27-28","gender":"f","style":"adult","mode":"historico","keyScene":false},{"index":7,"after":0,"name":"Elcaná","role":"Padre de Samuel.","title":"Una voz importante del relato","text":"Apoyó a su familia en los viajes para adorar y presentó sacrificios.","why":"Su hogar da contexto a la formación de Samuel.","reference":"1 Samuel 1:3-8; 2:18-21","gender":"m","style":"older","mode":"historico","keyScene":false},{"stage":"02 · EL PRIMER CAMBIO","name":"Samuel","role":"Joven que servía en el tabernáculo y llegó a ser profeta.","mode":"historico","title":"Una voz durante la noche","text":"Una noche Samuel oyó que alguien lo llamaba y fue a ver a Elí porque pensó que el sacerdote necesitaba algo.","why":"Samuel reaccionó con disposición a ayudar, aunque aún no comprendía quién lo llamaba.","reference":"1 Samuel 3:1–10","index":1,"keyScene":true,"after":1},{"index":8,"after":1,"name":"Elí","role":"Sumo sacerdote que supervisaba al joven Samuel.","title":"Una voz importante del relato","text":"Al principio no entendió quién llamaba a Samuel durante la noche.","why":"Finalmente le indicó al muchacho cómo responder.","reference":"1 Samuel 3:1-9","gender":"m","style":"older","mode":"historico","keyScene":false},{"stage":"03 · EL DESAFÍO","name":"Elí","role":"Sacerdote que supervisaba a Samuel en el tabernáculo.","mode":"historico","title":"La confusión se repite","text":"Samuel escuchó de nuevo su nombre y volvió a acudir a Elí. Esto ocurrió varias veces.","why":"La repetición mostró que necesitaba orientación para entender lo sucedido.","reference":"1 Samuel 3:1–10","index":2,"keyScene":true,"after":2},{"stage":"04 · LA RESPUESTA","name":"Elí","role":"Sacerdote que supervisaba a Samuel en el tabernáculo.","mode":"historico","title":"El consejo de Elí","text":"Elí comprendió que Jehová estaba llamando al muchacho y le explicó cómo responder.","why":"La guía de alguien con experiencia ayudó a Samuel.","reference":"1 Samuel 3:1–10","index":3,"keyScene":true,"after":3},{"index":9,"after":3,"name":"Hofní","role":"Hijo de Elí y sacerdote.","title":"Una voz importante del relato","text":"Se comportó con falta de respeto hacia los deberes del sacerdocio.","why":"Su conducta ayuda a entender por qué el mensaje recibido por Samuel era serio.","reference":"1 Samuel 2:12-17; 3:11-14","gender":"m","style":"adult","mode":"historico","keyScene":false},{"index":10,"after":3,"name":"Finehás","role":"Otro hijo de Elí.","title":"Una voz importante del relato","text":"Junto a su hermano recibió reprensión por su conducta.","why":"Se aprecia el contraste con la fidelidad que Samuel mostró de joven.","reference":"1 Samuel 2:22-26; 3:12-14","gender":"m","style":"adult","mode":"historico","keyScene":false},{"stage":"05 · EL PUNTO DECISIVO","name":"Samuel","role":"Joven que servía en el tabernáculo y llegó a ser profeta.","mode":"historico","title":"El mensaje que recibió","text":"Cuando volvió a escuchar la voz, Samuel se dispuso a escuchar. Recibió un mensaje serio para la casa de Elí.","why":"Escuchar también implicaría transmitir algo difícil.","reference":"1 Samuel 3:1–10","index":4,"keyScene":true,"after":4},{"stage":"06 · LAS CONSECUENCIAS","name":"Samuel","role":"Joven que servía en el tabernáculo y llegó a ser profeta.","mode":"historico","title":"Samuel crece como profeta","text":"Samuel fue reconocido como profeta fiel, y Jehová continuó utilizándolo para orientar a Israel.","why":"Su disposición a escuchar de joven marcó el comienzo de una vida de servicio.","reference":"1 Samuel 3:1–10","index":5,"keyScene":true,"after":5}],"jonatan":[{"stage":"01 · EL CONTEXTO","name":"Jonatán","role":"Hijo del rey Saúl y amigo leal de David.","mode":"historico","title":"Dos hombres y una amistad","text":"Jonatán era hijo de Saúl y heredero del trono; David se había distinguido por su valor. Entre ambos surgió una amistad muy estrecha.","why":"Jonatán no dejó que su posición social impidiera valorar a David.","reference":"1 Samuel 18:1–4; 23:16–18","index":0,"keyScene":true,"after":0},{"index":6,"after":0,"name":"Saúl","role":"Primer rey de Israel y padre de Jonatán.","title":"Una voz importante del relato","text":"Llegó a sentir celos de David e intentó dañarlo.","why":"Su oposición puso a prueba la amistad entre los dos jóvenes.","reference":"1 Samuel 18:8-11","gender":"m","style":"older","mode":"historico","keyScene":false},{"stage":"02 · EL PRIMER CAMBIO","name":"David","role":"Futuro rey de Israel; su amistad con Jonatán es muy conocida.","mode":"historico","title":"Un pacto de amistad","text":"Jonatán y David hicieron un pacto y Jonatán mostró afecto generoso hacia él.","why":"La amistad se basaba en lealtad, no en conveniencia.","reference":"1 Samuel 18:1–4; 23:16–18","index":1,"keyScene":true,"after":1},{"index":7,"after":1,"name":"Mical","role":"Hija de Saúl y esposa de David.","title":"Una voz importante del relato","text":"Ayudó a David a escapar de un intento de captura ordenado por su padre.","why":"Otro miembro de la familia real actuó para proteger a David.","reference":"1 Samuel 19:11-17","gender":"f","style":"young","mode":"historico","keyScene":false},{"stage":"03 · EL DESAFÍO","name":"Saúl","role":"Primer rey de Israel, padre de Jonatán.","mode":"historico","title":"La oposición de Saúl","text":"Saúl llegó a considerar a David una amenaza y trató de hacerle daño.","why":"Jonatán tuvo que elegir entre la hostilidad de su padre y lo que era justo.","reference":"1 Samuel 18:1–4; 23:16–18","index":2,"keyScene":true,"after":2},{"index":8,"after":2,"name":"Abner","role":"Jefe militar de Saúl.","title":"Una voz importante del relato","text":"Aparece entre los hombres de la corte que conocían a David.","why":"Ayuda a ubicar la historia dentro de la vida militar y política de Israel.","reference":"1 Samuel 17:55-58","gender":"m","style":"adult","mode":"historico","keyScene":false},{"stage":"04 · LA RESPUESTA","name":"Jonatán","role":"Hijo del rey Saúl y amigo leal de David.","mode":"historico","title":"Advertencia a David","text":"Jonatán ayudó a David a conocer el peligro y a evitar que lo alcanzaran.","why":"Su lealtad implicó actuar cuando un amigo estaba en peligro.","reference":"1 Samuel 18:1–4; 23:16–18","index":3,"keyScene":true,"after":3},{"index":9,"after":3,"name":"Ahimélec","role":"Sacerdote de Nob.","title":"Una voz importante del relato","text":"Ayudó a David cuando este estaba huyendo, sin conocer toda la situación.","why":"Su encuentro muestra las consecuencias que tuvo la persecución de David.","reference":"1 Samuel 21:1-9; 22:9-19","gender":"m","style":"older","mode":"historico","keyScene":false},{"stage":"05 · EL PUNTO DECISIVO","name":"Jonatán","role":"Hijo del rey Saúl y amigo leal de David.","mode":"historico","title":"Un encuentro en el desierto","text":"Cuando David estaba escondido, Jonatán fue a verlo y lo fortaleció para que siguiera confiando en Dios.","why":"No basta con sentir aprecio: una palabra oportuna puede sostener a otro.","reference":"1 Samuel 18:1–4; 23:16–18","index":4,"keyScene":true,"after":4},{"index":10,"after":4,"name":"David","role":"Amigo de Jonatán.","title":"Una voz importante del relato","text":"Recibió ánimo espiritual cuando Jonatán lo visitó mientras estaba escondido.","why":"La verdadera amistad lo fortaleció en un momento peligroso.","reference":"1 Samuel 23:16-18","gender":"m","style":"young","mode":"historico","keyScene":false},{"stage":"06 · LAS CONSECUENCIAS","name":"David","role":"Futuro rey de Israel; su amistad con Jonatán es muy conocida.","mode":"historico","title":"Lealtad hasta el final","text":"La amistad de ambos quedó como un ejemplo de apoyo sincero, incluso cuando sus circunstancias eran muy diferentes.","why":"La lealtad se demuestra en momentos difíciles.","reference":"1 Samuel 18:1–4; 23:16–18","index":5,"keyScene":true,"after":5}],"abigail":[{"stage":"01 · EL CONTEXTO","name":"David","role":"Futuro rey de Israel; su amistad con Jonatán es muy conocida.","mode":"historico","title":"Una petición rechazada","text":"David envió mensajeros para pedir ayuda a Nabal, un hombre rico a cuyos pastores los hombres de David habían protegido.","why":"El intercambio pudo resolverse de manera pacífica, pero no fue así.","reference":"1 Samuel 25:14–35","index":0,"keyScene":true,"after":0},{"index":6,"after":0,"name":"Mensajeros de David","role":"Hombres enviados a pedir provisiones.","title":"Una voz importante del relato","text":"Se dirigieron respetuosamente a Nabal para solicitar alimento.","why":"Su petición y la reacción de Nabal desencadenaron el conflicto.","reference":"1 Samuel 25:5-9","gender":"g","style":"group","mode":"historico","keyScene":false},{"stage":"02 · EL PRIMER CAMBIO","name":"Nabal","role":"Esposo de Abigaíl, cuya respuesta imprudente provocó un conflicto.","mode":"historico","title":"Una respuesta ofensiva","text":"Nabal respondió de forma despectiva, y David se enfureció al enterarse.","why":"Una provocación estaba a punto de provocar daños mucho mayores.","reference":"1 Samuel 25:14–35","index":1,"keyScene":true,"after":1},{"index":7,"after":1,"name":"Joven servidor de Nabal","role":"Siervo cuyo nombre no se registra.","title":"Una voz importante del relato","text":"Avisó a Abigaíl de que Nabal había ofendido a los hombres de David.","why":"Su advertencia permitió actuar antes de que se produjera violencia.","reference":"1 Samuel 25:14-17","gender":"m","style":"young","mode":"historico","keyScene":false},{"stage":"03 · EL DESAFÍO","name":"Joven servidor de Nabal","role":"Siervo que avisó a Abigaíl del peligro.","mode":"historico","title":"Un sirviente avisa","text":"Un servidor informó a Abigaíl, esposa de Nabal, sobre el peligro que se acercaba.","why":"Alguien tuvo la sensatez de buscar ayuda antes de que fuera tarde.","reference":"1 Samuel 25:14–35","index":2,"keyScene":true,"after":2},{"index":8,"after":2,"name":"Abigaíl","role":"Esposa de Nabal.","title":"Una voz importante del relato","text":"Reunió provisiones para evitar una tragedia y salió a hablar con David.","why":"Tomó la iniciativa de actuar con sensatez cuando había peligro.","reference":"1 Samuel 25:18-20","gender":"f","style":"adult","mode":"historico","keyScene":false},{"stage":"04 · LA RESPUESTA","name":"Abigaíl","role":"Mujer sensata que intervino para impedir una venganza.","mode":"historico","title":"Abigaíl prepara provisiones","text":"Sin perder tiempo, Abigaíl reunió alimentos y salió al encuentro de David.","why":"Su iniciativa fue rápida, concreta y orientada a evitar violencia.","reference":"1 Samuel 25:14–35","index":3,"keyScene":true,"after":3},{"index":9,"after":3,"name":"Siervas de Abigaíl","role":"Mujeres que servían en su casa.","title":"Una voz importante del relato","text":"La acompañaron cuando fue a casarse con David, después de la muerte de Nabal.","why":"Su presencia muestra la vida doméstica y las decisiones que siguieron.","reference":"1 Samuel 25:41-42","gender":"f","style":"group","mode":"historico","keyScene":false},{"stage":"05 · EL PUNTO DECISIVO","name":"Abigaíl","role":"Mujer sensata que intervino para impedir una venganza.","mode":"historico","title":"Palabras de paz","text":"Abigaíl habló con humildad y razonó con David para impedir una venganza impulsiva.","why":"Su tacto ayudó a cambiar el curso de los acontecimientos.","reference":"1 Samuel 25:14–35","index":4,"keyScene":true,"after":4},{"stage":"06 · LAS CONSECUENCIAS","name":"David","role":"Futuro rey de Israel; su amistad con Jonatán es muy conocida.","mode":"historico","title":"David escucha","text":"David aceptó el consejo y renunció a su propósito de vengarse de Nabal.","why":"Escuchar una corrección oportuna puede evitar errores irreparables.","reference":"1 Samuel 25:14–35","index":5,"keyScene":true,"after":5},{"index":10,"after":5,"name":"Nabal, final de su historia","role":"Esposo de Abigaíl.","title":"Una voz importante del relato","text":"Cuando supo lo ocurrido, quedó conmocionado; murió días después.","why":"El cierre del conflicto fue distinto de la venganza que David pensaba ejecutar.","reference":"1 Samuel 25:36-38","gender":"m","style":"older","mode":"historico","keyScene":false}],"salomon":[{"stage":"01 · EL CONTEXTO","name":"Salomón","role":"Hijo de David y rey de Israel, conocido por su sabiduría y el templo de Jerusalén.","mode":"historico","title":"Un rey preparado para una gran tarea","text":"David animó a su hijo Salomón a obedecer a Jehová y le dejó preparativos para el templo. Salomón heredó el trono.","why":"El propósito de construir el templo comenzó antes del proyecto de obra.","reference":"1 Crónicas 28:9-21; 1 Reyes 2:1-4","verseLabel":"1 Reyes 2:12","verseUrl":"https://www.jw.org/es/biblioteca/biblia/biblia-estudio/libros/1-reyes/2/","index":0,"keyScene":true,"after":0},{"index":6,"after":0,"name":"David, padre de Salomón","role":"Rey de Israel antes de Salomón.","title":"Una voz importante del relato","text":"Dio a su hijo consejos para servir a Jehová y preparó materiales para el templo.","why":"La construcción del templo tuvo raíces en preparativos anteriores al reinado de Salomón.","reference":"1 Crónicas 28:9-12; 29:1-5","gender":"m","style":"older","mode":"historico","keyScene":false},{"stage":"02 · EL PRIMER CAMBIO","name":"Salomón","role":"Hijo de David y rey de Israel, conocido por su sabiduría y el templo de Jerusalén.","mode":"historico","title":"Una petición en Gabaón","text":"En Gabaón, Jehová se apareció a Salomón en un sueño y lo invitó a pedir algo. Salomón no pidió riquezas ni una larga vida: pidió un corazón obediente para juzgar bien al pueblo.","why":"Jehová aprobó esa petición y le concedió sabiduría, además de otras bendiciones.","reference":"1 Reyes 3:5–12","verseLabel":"1 Reyes 3:4-15","verseUrl":"https://www.jw.org/es/biblioteca/biblia/biblia-estudio/libros/1-reyes/3/","index":1,"keyScene":true,"after":1},{"index":7,"after":1,"name":"Dos madres ante el rey","role":"Dos mujeres reclamaban al mismo niño.","title":"Una voz importante del relato","text":"Salomón buscó revelar quién amaba de verdad al bebé mediante una prueba.","why":"El episodio mostró la sabiduría práctica que recibió.","reference":"1 Reyes 3:16-28","gender":"f","style":"adult","mode":"historico","keyScene":false},{"stage":"03 · EL DESAFÍO","name":"Madre de la criatura","role":"Mujer cuyo nombre no aparece en el episodio del juicio.","mode":"historico","title":"El juicio de las dos madres","text":"Dos mujeres afirmaban ser la madre de un mismo bebé. Salomón propuso una prueba que reveló cuál de ellas amaba tanto al niño que prefería renunciar a él antes que verlo morir.","why":"Israel quedó impresionado porque reconoció la sabiduría de Dios en la decisión.","reference":"1 Reyes 3:5–12","verseLabel":"1 Reyes 3:16-28","verseUrl":"https://www.jw.org/es/biblioteca/biblia/biblia-estudio/libros/1-reyes/3/","index":2,"keyScene":true,"after":2},{"index":8,"after":2,"name":"Madre que protegió al bebé","role":"Mujer cuyo nombre no registra el relato.","title":"Una voz importante del relato","text":"Prefería renunciar al niño antes que verlo lastimado.","why":"El amor de la verdadera madre permitió resolver el caso.","reference":"1 Reyes 3:26-27","gender":"f","style":"adult","mode":"historico","keyScene":false},{"stage":"04 · LA RESPUESTA","name":"Hiram de Tiro","role":"Rey de Tiro que colaboró con Salomón en el suministro de madera y materiales.","mode":"historico","title":"El templo empieza a levantarse","text":"Siguiendo los preparativos de David, Salomón organizó obreros, materiales y madera de cedro obtenida mediante acuerdos con Hiram, rey de Tiro. El templo se construyó en Jerusalén.","why":"El trabajo duró aproximadamente siete años y reunió a muchos trabajadores capacitados.","reference":"1 Reyes 3:5–12","verseLabel":"1 Reyes 5-6","verseUrl":"https://www.jw.org/es/biblioteca/biblia/biblia-estudio/libros/1-reyes/6/","index":3,"keyScene":true,"after":3},{"index":9,"after":3,"name":"Hiram de Tiro","role":"Rey de Tiro, aliado de Salomón.","title":"Una voz importante del relato","text":"Facilitó madera y otros recursos para la obra del templo.","why":"Hubo organización internacional de materiales y trabajo.","reference":"1 Reyes 5:1-12","gender":"m","style":"older","mode":"historico","keyScene":false},{"index":10,"after":3,"name":"Hiram, artesano de bronce","role":"Especialista que trabajó en las columnas y piezas de bronce.","title":"Una voz importante del relato","text":"Fabricó elementos elaborados para el templo.","why":"Su destreza artística aportó a la construcción.","reference":"1 Reyes 7:13-47","gender":"m","style":"adult","mode":"historico","keyScene":false},{"stage":"05 · EL PUNTO DECISIVO","name":"Sacerdotes del templo","role":"Grupo que participó en la dedicación del templo.","mode":"historico","title":"La dedicación del templo","text":"Cuando terminaron las obras, llevaron el arca del pacto al templo. Salomón hizo una oración pública reconociendo que ningún edificio puede contener a Jehová, y pidió que escuchara las oraciones de su pueblo.","why":"Según 2 Crónicas 7, fuego del cielo consumió las ofrendas y el pueblo se alegró.","reference":"1 Reyes 3:5–12","verseLabel":"1 Reyes 8; 2 Crónicas 7:1","verseUrl":"https://www.jw.org/es/biblioteca/biblia/biblia-estudio/libros/1-reyes/8/","index":4,"keyScene":true,"after":4},{"index":11,"after":4,"name":"Sacerdotes del templo","role":"Servidores religiosos, mencionados como grupo.","title":"Una voz importante del relato","text":"Llevaron el arca del pacto al lugar santísimo cuando se dedicó el templo.","why":"La dedicación fue un acontecimiento colectivo de adoración.","reference":"1 Reyes 8:1-11","gender":"g","style":"group","mode":"historico","keyScene":false},{"stage":"06 · LAS CONSECUENCIAS","name":"Reina de Saba","role":"Soberana que viajó para comprobar la sabiduría de Salomón.","mode":"historico","title":"La reina de Saba y lo que siguió","text":"La reina de Saba llegó con preguntas difíciles para poner a prueba la fama de Salomón. Sus respuestas y la prosperidad del reino la impresionaron. Sin embargo, más adelante Salomón permitió influencias que lo apartaron de la adoración fiel.","why":"La historia enseña que adquirir sabiduría es importante, pero seguir obedeciendo durante toda la vida también lo es.","reference":"1 Reyes 3:5–12","verseLabel":"1 Reyes 10-11","verseUrl":"https://www.jw.org/es/biblioteca/biblia/biblia-estudio/libros/1-reyes/10/","index":5,"keyScene":true,"after":5},{"index":12,"after":5,"name":"Reina de Saba","role":"Gobernante extranjera que viajó para conocer a Salomón.","title":"Una voz importante del relato","text":"Planteó preguntas difíciles y quedó impresionada por su sabiduría y su reino.","why":"Su visita divulgó la reputación de la sabiduría concedida a Salomón.","reference":"1 Reyes 10:1-9","gender":"f","style":"adult","mode":"historico","keyScene":false}],"viuda":[{"stage":"01 · EL CONTEXTO","name":"Viuda de Sarepta","role":"Mujer cuyo nombre no se conserva en el relato; ayudó a Elías durante una gran escasez.","mode":"historico","title":"Una época de sequía","text":"Durante una gran sequía, la comida escaseaba y una viuda en Sarepta tenía muy pocas provisiones para ella y su hijo.","why":"La situación planteaba una necesidad inmediata de supervivencia.","reference":"1 Reyes 17:8–16","index":0,"keyScene":true,"after":0},{"index":6,"after":0,"name":"Hijo de la viuda","role":"Hijo de la viuda de Sarepta; nombre no registrado.","title":"Una voz importante del relato","text":"Vivía con su madre durante la escasez de alimentos.","why":"El suministro milagroso sostuvo a ambas personas.","reference":"1 Reyes 17:12-16","gender":"m","style":"child","mode":"historico","keyScene":false},{"stage":"02 · EL PRIMER CAMBIO","name":"Elías","role":"Profeta que recibió ayuda y alimento durante una época de sequía.","mode":"historico","title":"Elías llega a Sarepta","text":"El profeta Elías, siguiendo las instrucciones de Jehová, encontró a la viuda recogiendo leña.","why":"El encuentro parecía común, pero dio comienzo a una prueba de confianza.","reference":"1 Reyes 17:8–16","index":1,"keyScene":true,"after":1},{"index":7,"after":1,"name":"Elías","role":"Profeta de Jehová.","title":"Una voz importante del relato","text":"Pidió agua y pan a la viuda en una época de sequía.","why":"Sus palabras plantearon una prueba de confianza en la promesa de Jehová.","reference":"1 Reyes 17:8-14","gender":"m","style":"older","mode":"historico","keyScene":false},{"stage":"03 · EL DESAFÍO","name":"Viuda de Sarepta","role":"Mujer cuyo nombre no se conserva en el relato; ayudó a Elías durante una gran escasez.","mode":"historico","title":"Una petición difícil","text":"Elías pidió agua y un poco de pan. La mujer explicó que apenas tenía harina y aceite para una última comida.","why":"La petición tenía un gran peso dadas sus circunstancias.","reference":"1 Reyes 17:8–16","index":2,"keyScene":true,"after":2},{"index":8,"after":2,"name":"Viuda de Sarepta","role":"Mujer que vivía con pocos recursos.","title":"Una voz importante del relato","text":"Preparó alimento para Elías pese a que solo tenía un poco de harina y aceite.","why":"Actuó con fe y hospitalidad aun en medio de necesidad.","reference":"1 Reyes 17:12-15","gender":"f","style":"adult","mode":"historico","keyScene":false},{"stage":"04 · LA RESPUESTA","name":"Elías","role":"Profeta que recibió ayuda y alimento durante una época de sequía.","mode":"historico","title":"La decisión de compartir","text":"Elías le aseguró que Jehová proveería. La viuda preparó alimento y lo compartió con él.","why":"La mujer actuó a pesar de la escasez que la rodeaba.","reference":"1 Reyes 17:8–16","index":3,"keyScene":true,"after":3},{"stage":"05 · EL PUNTO DECISIVO","name":"Viuda de Sarepta","role":"Mujer cuyo nombre no se conserva en el relato; ayudó a Elías durante una gran escasez.","mode":"historico","title":"Harina y aceite suficientes","text":"Durante ese período, la harina y el aceite no se agotaron, tal como se había anunciado.","why":"El relato muestra provisión diaria, no una desaparición inmediata de toda dificultad.","reference":"1 Reyes 17:8–16","index":4,"keyScene":true,"after":4},{"index":9,"after":4,"name":"Hijo enfermo","role":"El mismo hijo de la viuda, en un suceso posterior.","title":"Una voz importante del relato","text":"Enfermó gravemente y murió; Elías oró por él y recobró la vida.","why":"El capítulo también registra una respuesta extraordinaria a la oración de Elías.","reference":"1 Reyes 17:17-24","gender":"m","style":"child","mode":"historico","keyScene":false},{"stage":"06 · LAS CONSECUENCIAS","name":"Viuda de Sarepta","role":"Mujer que sobrevivió con su hijo durante la sequía.","mode":"historico","title":"Lo que enseña Sarepta","text":"La viuda y su hijo pudieron seguir alimentándose durante la sequía.","why":"En momentos de preocupación, la confianza puede demostrarse en actos concretos de generosidad.","reference":"1 Reyes 17:8–16","index":5,"keyScene":true,"after":5}],"naaman":[{"stage":"01 · EL CONTEXTO","name":"Naamán","role":"Jefe del ejército de Siria que sufría una enfermedad de la piel.","mode":"historico","title":"Un jefe militar enfermo","text":"Naamán era un jefe del ejército sirio muy respetado, pero padecía una grave enfermedad de la piel.","why":"La posición social no eliminaba sus problemas personales.","reference":"2 Reyes 5:1–15","index":0,"keyScene":true,"after":0},{"index":6,"after":0,"name":"Esposa de Naamán","role":"Esposa del jefe militar sirio.","title":"Una voz importante del relato","text":"Escuchó a la niña israelita hablar sobre un profeta de Samaria.","why":"Una conversación en el hogar abrió camino a buscar ayuda.","reference":"2 Reyes 5:2-4","gender":"f","style":"adult","mode":"historico","keyScene":false},{"stage":"02 · EL PRIMER CAMBIO","name":"Niña israelita","role":"Joven cautiva cuyo nombre no se conoce; habló de Eliseo a la familia de Naamán.","mode":"historico","title":"Una niña israelita habla","text":"Una joven israelita cautiva que trabajaba para la esposa de Naamán dijo que el profeta Eliseo podía ayudarlo.","why":"Una persona sin poder político compartió una información decisiva.","reference":"2 Reyes 5:1–15","index":1,"keyScene":true,"after":1},{"index":7,"after":1,"name":"Niña israelita","role":"Joven cautiva al servicio de la esposa de Naamán.","title":"Una voz importante del relato","text":"Expresó confianza en que el profeta de Israel podría curar a Naamán.","why":"Su valor hizo llegar una esperanza a alguien poderoso.","reference":"2 Reyes 5:2-3","gender":"f","style":"child","mode":"historico","keyScene":false},{"stage":"03 · EL DESAFÍO","name":"Naamán","role":"Jefe del ejército de Siria que sufría una enfermedad de la piel.","mode":"historico","title":"El viaje a Israel","text":"Naamán viajó llevando regalos y una carta. Finalmente llegó a la casa de Eliseo.","why":"Esperaba recibir ayuda y quizá un trato especial.","reference":"2 Reyes 5:1–15","index":2,"keyScene":true,"after":2},{"index":8,"after":2,"name":"Rey de Siria","role":"Gobernante que apoyó el viaje de Naamán.","title":"Una voz importante del relato","text":"Envió una carta al rey de Israel solicitando ayuda.","why":"Su acción llevó el asunto a la corte israelita.","reference":"2 Reyes 5:4-6","gender":"m","style":"older","mode":"historico","keyScene":false},{"stage":"04 · LA RESPUESTA","name":"Eliseo","role":"Profeta de Jehová que dio a Naamán las instrucciones para curarse.","mode":"historico","title":"Instrucciones inesperadas","text":"Eliseo envió un mensaje: Naamán debía bañarse siete veces en el río Jordán. Naamán se molestó porque esperaba una ceremonia más impresionante.","why":"Su orgullo casi le impide aceptar una solución sencilla.","reference":"2 Reyes 5:1–15","index":3,"keyScene":true,"after":3},{"index":9,"after":3,"name":"Guehazí","role":"Siervo de Eliseo.","title":"Una voz importante del relato","text":"Estuvo vinculado a la casa del profeta, pero después buscó un beneficio personal indebido.","why":"Su decisión contrasta con la gratitud y humildad que se destacan en Naamán.","reference":"2 Reyes 5:20-27","gender":"m","style":"young","mode":"historico","keyScene":false},{"stage":"05 · EL PUNTO DECISIVO","name":"Siervos de Naamán","role":"Acompañantes que lo persuadieron de obedecer.","mode":"historico","title":"Los servidores razonan","text":"Los acompañantes de Naamán lo animaron a seguir las indicaciones aunque parecieran demasiado simples.","why":"Escuchar a quienes nos ayudan puede cambiar una reacción impulsiva.","reference":"2 Reyes 5:1–15","index":4,"keyScene":true,"after":4},{"index":10,"after":4,"name":"Siervos de Naamán","role":"Acompañantes de Naamán; sus nombres no se registran.","title":"Una voz importante del relato","text":"Lo animaron a obedecer una instrucción aparentemente sencilla.","why":"Sus palabras ayudaron a que dejara a un lado el orgullo.","reference":"2 Reyes 5:13-14","gender":"g","style":"group","mode":"historico","keyScene":false},{"stage":"06 · LAS CONSECUENCIAS","name":"Naamán","role":"Jefe del ejército de Siria que sufría una enfermedad de la piel.","mode":"historico","title":"La curación","text":"Naamán se sumergió siete veces en el Jordán y quedó sano. Después reconoció al Dios de Israel.","why":"La humildad y la obediencia terminaron siendo más importantes que el prestigio.","reference":"2 Reyes 5:1–15","index":5,"keyScene":true,"after":5}],"jonas":[{"stage":"01 · EL CONTEXTO","name":"Jonás","role":"Profeta enviado a anunciar una advertencia en Nínive.","mode":"historico","title":"Una misión a Nínive","text":"Jehová encargó a Jonás que advirtiera a los habitantes de Nínive sobre su conducta.","why":"El profeta recibió una tarea que no deseaba cumplir.","reference":"Jonás 3:1–10; 4:1–11","index":0,"keyScene":true,"after":0},{"index":6,"after":0,"name":"Marineros","role":"Tripulación del barco al que subió Jonás.","title":"Una voz importante del relato","text":"En plena tormenta buscaron salvar el barco y averiguar por qué ocurría aquella calamidad.","why":"Su reacción muestra el peligro causado por la huida de Jonás.","reference":"Jonás 1:4-11","gender":"g","style":"group","mode":"historico","keyScene":false},{"stage":"02 · EL PRIMER CAMBIO","name":"Marineros","role":"Grupo que estuvo con Jonás durante la tormenta.","mode":"historico","title":"Huida por mar","text":"Jonás tomó un barco con destino contrario al que debía ir. Durante el viaje surgió una fuerte tormenta.","why":"Huir de la responsabilidad no eliminó el problema.","reference":"Jonás 3:1–10; 4:1–11","index":1,"keyScene":true,"after":1},{"index":7,"after":1,"name":"Capitán del barco","role":"Responsable de la embarcación; no se registra su nombre.","title":"Una voz importante del relato","text":"Pidió a Jonás que se levantara y orara cuando los demás estaban en peligro.","why":"El episodio subraya la gravedad de la tormenta.","reference":"Jonás 1:5-6","gender":"m","style":"older","mode":"historico","keyScene":false},{"stage":"03 · EL DESAFÍO","name":"Jonás","role":"Profeta enviado a anunciar una advertencia en Nínive.","mode":"historico","title":"Una experiencia extraordinaria","text":"Jonás fue arrojado al mar y un gran pez lo tragó. Desde su interior oró, y después fue devuelto a tierra firme.","why":"Aquella experiencia le dio una nueva oportunidad.","reference":"Jonás 3:1–10; 4:1–11","index":2,"keyScene":true,"after":2},{"stage":"04 · LA RESPUESTA","name":"Jonás","role":"Profeta enviado a anunciar una advertencia en Nínive.","mode":"historico","title":"Nínive escucha","text":"Jonás fue finalmente a Nínive y proclamó el aviso. Los habitantes tomaron en serio el mensaje y cambiaron su conducta.","why":"La reacción de la ciudad contrastó con las expectativas de Jonás.","reference":"Jonás 3:1–10; 4:1–11","index":3,"keyScene":true,"after":3},{"index":8,"after":3,"name":"Rey de Nínive","role":"Gobernante de la ciudad; nombre no indicado.","title":"Una voz importante del relato","text":"Se quitó sus prendas reales y participó en el arrepentimiento público.","why":"Su reacción contribuyó a que la ciudad cambiara de conducta.","reference":"Jonás 3:6-9","gender":"m","style":"older","mode":"historico","keyScene":false},{"index":9,"after":3,"name":"Habitantes de Nínive","role":"Población de la ciudad; intervención colectiva.","title":"Una voz importante del relato","text":"Escucharon la advertencia y cambiaron su conducta.","why":"El resultado ayuda a explicar por qué Jehová mostró misericordia.","reference":"Jonás 3:5-10","gender":"g","style":"group","mode":"historico","keyScene":false},{"stage":"05 · EL PUNTO DECISIVO","name":"Jonás","role":"Profeta enviado a anunciar una advertencia en Nínive.","mode":"historico","title":"Jonás se disgusta","text":"Cuando Jehová mostró compasión, Jonás se enojó porque Nínive no fue destruida.","why":"Cumplir una tarea no siempre significa comprender todavía el corazón de quien la encargó.","reference":"Jonás 3:1–10; 4:1–11","index":4,"keyScene":true,"after":4},{"stage":"06 · LAS CONSECUENCIAS","name":"Jonás","role":"Profeta a quien se enseñó una lección de misericordia.","mode":"historico","title":"La lección de la planta","text":"Jehová utilizó una planta y su pérdida para ayudar a Jonás a reflexionar sobre la compasión por otras personas.","why":"La misericordia fue la lección final de esta historia.","reference":"Jonás 3:1–10; 4:1–11","index":5,"keyScene":true,"after":5},{"index":10,"after":5,"name":"Jonás ante la planta","role":"El mismo profeta en el episodio final.","title":"Una voz importante del relato","text":"Aprendió una lección cuando la planta que le daba sombra se marchitó.","why":"El desenlace plantea reflexionar sobre la compasión.","reference":"Jonás 4:6-11","gender":"m","style":"adult","mode":"historico","keyScene":false}],"josias":[{"stage":"01 · EL CONTEXTO","name":"Josías","role":"Rey de Judá que empezó a gobernar siendo niño e impulsó reformas.","mode":"historico","title":"Un niño rey","text":"Josías llegó a ser rey de Judá cuando tenía solo ocho años.","why":"Su edad no impidió que con el tiempo buscara hacer lo correcto.","reference":"2 Reyes 22:8–13; 23:1–3","index":0,"keyScene":true,"after":0},{"index":6,"after":0,"name":"Amón","role":"Padre de Josías y rey anterior.","title":"Una voz importante del relato","text":"Su reinado terminó cuando fue asesinado por sus propios siervos.","why":"Josías asumió el trono siendo todavía niño.","reference":"2 Reyes 21:19-26","gender":"m","style":"older","mode":"historico","keyScene":false},{"stage":"02 · EL PRIMER CAMBIO","name":"Josías","role":"Rey de Judá que empezó a gobernar siendo niño e impulsó reformas.","mode":"historico","title":"El deseo de agradar a Dios","text":"Mientras crecía, Josías quiso restablecer la adoración a Jehová y dejar atrás prácticas incorrectas.","why":"El cambio comenzó antes del descubrimiento del libro.","reference":"2 Reyes 22:8–13; 23:1–3","index":1,"keyScene":true,"after":1},{"index":7,"after":1,"name":"Hilquías","role":"Sumo sacerdote.","title":"Una voz importante del relato","text":"Durante las reparaciones del templo encontró el libro de la Ley.","why":"Su hallazgo hizo posible que la nación oyera de nuevo las exigencias escritas.","reference":"2 Reyes 22:8","gender":"m","style":"older","mode":"historico","keyScene":false},{"index":10,"after":1,"name":"Jeremías","role":"Profeta contemporáneo de Josías.","title":"Una voz importante del relato","text":"Su ministerio comenzó durante los años del reinado de Josías.","why":"Su presencia ayuda a ubicar el período profético de la reforma.","reference":"Jeremías 1:1-3","gender":"m","style":"young","mode":"historico","keyScene":false},{"stage":"03 · EL DESAFÍO","name":"Hilquías","role":"Sumo sacerdote que halló el libro de la Ley durante reparaciones del templo.","mode":"historico","title":"Reparaciones del templo","text":"Se organizaron trabajos para reparar el templo, que había sufrido descuido.","why":"Restaurar un lugar de adoración implicaba esfuerzo y administración.","reference":"2 Reyes 22:8–13; 23:1–3","index":2,"keyScene":true,"after":2},{"index":8,"after":2,"name":"Safán","role":"Secretario del rey Josías.","title":"Una voz importante del relato","text":"Recibió el libro y lo leyó ante el rey.","why":"Su lectura llevó a Josías a tomar en serio las advertencias.","reference":"2 Reyes 22:9-11","gender":"m","style":"adult","mode":"historico","keyScene":false},{"stage":"04 · LA RESPUESTA","name":"Safán","role":"Secretario que leyó ante Josías el contenido del libro encontrado.","mode":"historico","title":"Encuentran el libro de la Ley","text":"Durante las obras, el sumo sacerdote Hilquías encontró el libro de la Ley y se lo entregó al secretario Safán.","why":"El hallazgo puso delante del rey las normas que muchos habían desatendido.","reference":"2 Reyes 22:8–13; 23:1–3","index":3,"keyScene":true,"after":3},{"stage":"05 · EL PUNTO DECISIVO","name":"Josías","role":"Rey de Judá que empezó a gobernar siendo niño e impulsó reformas.","mode":"historico","title":"Josías escucha","text":"Safán leyó el libro ante el rey. Josías reaccionó con gran preocupación al comprender cuánto se había apartado el pueblo de la Ley.","why":"Su reacción mostró respeto por lo que había aprendido.","reference":"2 Reyes 22:8–13; 23:1–3","index":4,"keyScene":true,"after":4},{"index":9,"after":4,"name":"Huldá","role":"Profetisa consultada por los enviados del rey.","title":"Una voz importante del relato","text":"Transmitió la respuesta divina sobre las consecuencias de las desobediencias del pueblo.","why":"Su mensaje confirmó la importancia de la reforma.","reference":"2 Reyes 22:14-20","gender":"f","style":"older","mode":"historico","keyScene":false},{"stage":"06 · LAS CONSECUENCIAS","name":"Josías","role":"Rey de Judá que empezó a gobernar siendo niño e impulsó reformas.","mode":"historico","title":"Medidas de reforma","text":"Josías reunió al pueblo, renovó el pacto y promovió acciones para abandonar la idolatría.","why":"La comprensión del mensaje llevó a cambios visibles.","reference":"2 Reyes 22:8–13; 23:1–3","index":5,"keyScene":true,"after":5}],"daniel":[{"stage":"01 · EL CONTEXTO","name":"Daniel","role":"Siervo de Jehová y funcionario en Babilonia y bajo el dominio medopersa.","mode":"historico","title":"Un joven lejos de Jerusalén","text":"Daniel y tres compañeros fueron llevados a Babilonia y recibieron formación para servir en la corte.","why":"Desde su juventud, Daniel mostró la importancia de mantener sus convicciones.","reference":"Daniel 1:1-21","index":0,"keyScene":true,"after":0},{"index":6,"after":0,"name":"Ananías","role":"Compañero hebreo de Daniel.","title":"Una voz importante del relato","text":"Junto a Daniel y otros jóvenes decidió seguir fiel a Jehová en Babilonia.","why":"Su firmeza forma parte del contexto de la historia de Daniel.","reference":"Daniel 1:6-20","gender":"m","style":"young","mode":"historico","keyScene":false},{"index":7,"after":0,"name":"Misael","role":"Compañero hebreo de Daniel.","title":"Una voz importante del relato","text":"Participó en la prueba sobre alimento en la corte.","why":"Compartió decisiones de conciencia con Daniel.","reference":"Daniel 1:6-20","gender":"m","style":"young","mode":"historico","keyScene":false},{"index":8,"after":0,"name":"Azarías","role":"Compañero hebreo de Daniel.","title":"Una voz importante del relato","text":"Se mantuvo fiel con Daniel, Ananías y Misael.","why":"No fue un único joven quien mostró valor en aquel ambiente.","reference":"Daniel 1:6-20","gender":"m","style":"young","mode":"historico","keyScene":false},{"stage":"02 · EL PRIMER CAMBIO","name":"Funcionarios del reino","role":"Funcionarios que estaban celosos de Daniel.","mode":"historico","title":"Una prohibición calculada","text":"Algunos funcionarios impulsaron un decreto que impedía dirigir peticiones a otro que no fuera el rey durante cierto tiempo.","why":"La trampa se diseñó para aprovechar la costumbre de Daniel de orar a Jehová.","reference":"Daniel 6:4–23","index":1,"keyScene":true,"after":1},{"index":9,"after":1,"name":"Funcionarios celosos","role":"Grupo de altos funcionarios de la corte persa.","title":"Una voz importante del relato","text":"Buscaron una acusación contra Daniel y promovieron una prohibición de orar.","why":"La amenaza surgió de un plan deliberado contra su integridad.","reference":"Daniel 6:4-9","gender":"g","style":"group","mode":"historico","keyScene":false},{"stage":"03 · EL DESAFÍO","name":"Daniel","role":"Siervo de Jehová y funcionario en Babilonia y bajo el dominio medopersa.","mode":"historico","title":"Daniel sigue orando","text":"Daniel continuó orando tres veces al día, como hacía antes de la prohibición.","why":"No cambió su adoración solo porque otros intentaran presionarlo.","reference":"Daniel 6:4–23","index":2,"keyScene":true,"after":2},{"stage":"04 · LA RESPUESTA","name":"Rey Darío","role":"Rey que tuvo que aplicar la ley que había firmado.","mode":"historico","title":"El hoyo de los leones","text":"Los funcionarios lo denunciaron, y el rey se vio obligado a ordenar que Daniel fuera arrojado al hoyo.","why":"La decisión de mantenerse fiel tuvo una consecuencia peligrosa.","reference":"Daniel 6:4–23","index":3,"keyScene":true,"after":3},{"index":10,"after":3,"name":"Rey Darío","role":"Rey persa citado en Daniel 6.","title":"Una voz importante del relato","text":"Reconoció el peligro de la ley que había autorizado y deseaba librar a Daniel.","why":"El decreto no permitió que el monarca cambiara la sentencia a tiempo.","reference":"Daniel 6:14-18","gender":"m","style":"older","mode":"historico","keyScene":false},{"stage":"05 · EL PUNTO DECISIVO","name":"Daniel","role":"Siervo de Jehová y funcionario en Babilonia y bajo el dominio medopersa.","mode":"historico","title":"La noche de protección","text":"Daniel pasó la noche entre leones. Según el relato, Jehová envió un ángel que les cerró la boca.","why":"La intervención divina es el momento decisivo de la historia.","reference":"Daniel 6:4–23","index":4,"keyScene":true,"after":4},{"index":11,"after":4,"name":"Ángel enviado por Dios","role":"Mensajero espiritual; representación simbólica.","title":"Una voz importante del relato","text":"Daniel explicó que Dios envió a su ángel para cerrar la boca de los leones.","why":"El relato atribuye la protección a la intervención de Dios.","reference":"Daniel 6:21-23","gender":"g","style":"angel","mode":"historico","keyScene":false},{"stage":"06 · LAS CONSECUENCIAS","name":"Rey Darío","role":"Gobernante que fue informado de que Daniel había sido arrojado a los leones.","mode":"historico","title":"Una noticia al amanecer","text":"El rey fue al hoyo muy temprano y encontró a Daniel vivo.","why":"El final confirma por qué la fidelidad de Daniel se recuerda tanto.","reference":"Daniel 6:4–23","index":5,"keyScene":true,"after":5}],"ester":[{"stage":"01 · EL CONTEXTO","name":"Ester","role":"Reina judía en Persia que intervino para proteger a su pueblo.","mode":"historico","title":"Una joven llega a ser reina","text":"Ester, una joven judía criada por su primo Mardoqueo, llegó a ser reina en Persia.","why":"Su nueva posición la colocó cerca de decisiones que afectarían a muchas personas.","reference":"Ester 4:10–17; 5:1–8; 7:1–6","index":0,"keyScene":true,"after":0},{"index":6,"after":0,"name":"Rey Asuero","role":"Rey persa, esposo de Ester.","title":"Una voz importante del relato","text":"Eligió a Ester como reina sin saber aún que pertenecía al pueblo judío.","why":"Su posición hizo decisiva la intervención posterior de Ester.","reference":"Ester 2:15-18","gender":"m","style":"older","mode":"historico","keyScene":false},{"stage":"02 · EL PRIMER CAMBIO","name":"Mardoqueo","role":"Primo de Ester que la había criado y la animó a actuar.","mode":"historico","title":"El plan de Hamán","text":"Hamán ideó un plan para exterminar a los judíos del imperio y consiguió una orden real.","why":"El peligro amenazaba a todo el pueblo de Ester.","reference":"Ester 4:10–17; 5:1–8; 7:1–6","index":1,"keyScene":true,"after":1},{"index":7,"after":1,"name":"Hamán","role":"Funcionario de alto rango que odiaba a Mardoqueo.","title":"Una voz importante del relato","text":"Consiguió un decreto contra los judíos del imperio.","why":"Su plan hizo urgente la petición de Ester.","reference":"Ester 3:5-13","gender":"m","style":"adult","mode":"historico","keyScene":false},{"stage":"03 · EL DESAFÍO","name":"Mardoqueo","role":"Primo de Ester que la había criado y la animó a actuar.","mode":"historico","title":"Mardoqueo pide ayuda","text":"Mardoqueo pidió a Ester que interviniera ante el rey. Acercarse al rey sin invitación podía poner en riesgo su vida.","why":"Ester tuvo que valorar tanto el peligro como la responsabilidad.","reference":"Ester 4:10–17; 5:1–8; 7:1–6","index":2,"keyScene":true,"after":2},{"index":8,"after":2,"name":"Hatac","role":"Funcionario que atendía a Ester.","title":"Una voz importante del relato","text":"Transmitió mensajes entre Ester y Mardoqueo.","why":"Facilitó que ambos coordinaran sus decisiones durante el peligro.","reference":"Ester 4:5-9","gender":"m","style":"adult","mode":"historico","keyScene":false},{"stage":"04 · LA RESPUESTA","name":"Ester","role":"Reina judía en Persia que intervino para proteger a su pueblo.","mode":"historico","title":"Preparación antes de actuar","text":"Ester solicitó que los judíos ayunaran y se preparó para presentarse ante el rey.","why":"No improvisó: buscó apoyo y eligió con cuidado el momento.","reference":"Ester 4:10–17; 5:1–8; 7:1–6","index":3,"keyScene":true,"after":3},{"index":9,"after":3,"name":"Judíos de Susa","role":"Miembros de la comunidad judía.","title":"Una voz importante del relato","text":"Participaron en el ayuno que Ester solicitó.","why":"La respuesta colectiva acompañó la decisión valiente de Ester.","reference":"Ester 4:15-17","gender":"g","style":"group","mode":"historico","keyScene":false},{"stage":"05 · EL PUNTO DECISIVO","name":"Ester","role":"Reina judía en Persia que intervino para proteger a su pueblo.","mode":"historico","title":"Los banquetes","text":"El rey recibió favorablemente a Ester. Ella organizó banquetes y preparó la ocasión para revelar su petición.","why":"La valentía de Ester estuvo acompañada de prudencia.","reference":"Ester 4:10–17; 5:1–8; 7:1–6","index":4,"keyScene":true,"after":4},{"index":10,"after":4,"name":"Harboná","role":"Funcionario de la corte.","title":"Una voz importante del relato","text":"Informó que Hamán había preparado un madero para Mardoqueo.","why":"Su intervención aceleró el desenlace del plan de Hamán.","reference":"Ester 7:9-10","gender":"m","style":"adult","mode":"historico","keyScene":false},{"stage":"06 · LAS CONSECUENCIAS","name":"Ester","role":"Reina judía en Persia que intervino para proteger a su pueblo.","mode":"historico","title":"La amenaza sale a la luz","text":"En el momento oportuno, Ester identificó a Hamán como el responsable de la amenaza contra su pueblo.","why":"La acción valiente de Ester ayudó a cambiar el desenlace.","reference":"Ester 4:10–17; 5:1–8; 7:1–6","index":5,"keyScene":true,"after":5}],"nehemias":[{"stage":"01 · EL CONTEXTO","name":"Nehemías","role":"Copero del rey persa que dirigió la reconstrucción de la muralla de Jerusalén.","mode":"historico","title":"Malas noticias de Jerusalén","text":"Nehemías, que servía en la corte persa, se enteró de que las murallas de Jerusalén seguían en ruinas.","why":"La noticia lo afectó porque la ciudad y su pueblo le importaban.","reference":"Nehemías 2:11–18; 3:1–32; 6:15","index":0,"keyScene":true,"after":0},{"index":6,"after":0,"name":"Hananí","role":"Hermano de Nehemías.","title":"Una voz importante del relato","text":"Trajo noticias sobre las dificultades y murallas derribadas de Jerusalén.","why":"Sus noticias impulsaron a Nehemías a orar y actuar.","reference":"Nehemías 1:2-4","gender":"m","style":"adult","mode":"historico","keyScene":false},{"stage":"02 · EL PRIMER CAMBIO","name":"Nehemías","role":"Copero del rey persa que dirigió la reconstrucción de la muralla de Jerusalén.","mode":"historico","title":"Oración y preparación","text":"Nehemías oró y preparó una petición al rey para poder viajar y ayudar.","why":"Combinó dependencia de Jehová con planificación concreta.","reference":"Nehemías 2:11–18; 3:1–32; 6:15","index":1,"keyScene":true,"after":1},{"index":7,"after":1,"name":"Rey Artajerjes","role":"Rey persa para quien trabajaba Nehemías.","title":"Una voz importante del relato","text":"Escuchó su petición y autorizó el viaje a Jerusalén.","why":"Su permiso abrió la posibilidad de reconstruir la muralla.","reference":"Nehemías 2:1-8","gender":"m","style":"older","mode":"historico","keyScene":false},{"stage":"03 · EL DESAFÍO","name":"Nehemías","role":"Copero del rey persa que dirigió la reconstrucción de la muralla de Jerusalén.","mode":"historico","title":"Una inspección nocturna","text":"Al llegar a Jerusalén, Nehemías examinó de noche los daños de la muralla antes de explicar sus planes.","why":"Quiso conocer personalmente la situación antes de organizar el trabajo.","reference":"Nehemías 2:11–18; 3:1–32; 6:15","index":2,"keyScene":true,"after":2},{"index":8,"after":2,"name":"Eliasib","role":"Sumo sacerdote.","title":"Una voz importante del relato","text":"Comenzó la reparación de la puerta de las Ovejas con otros sacerdotes.","why":"El relato describe participación de diferentes grupos sociales.","reference":"Nehemías 3:1","gender":"m","style":"older","mode":"historico","keyScene":false},{"stage":"04 · LA RESPUESTA","name":"Constructores de Jerusalén","role":"Grupo que trabajó en la reconstrucción.","mode":"historico","title":"Manos a la obra","text":"Diferentes familias y grupos comenzaron a reconstruir secciones de la muralla.","why":"La cooperación permitió avanzar en una obra demasiado grande para una sola persona.","reference":"Nehemías 2:11–18; 3:1–32; 6:15","index":3,"keyScene":true,"after":3},{"index":9,"after":3,"name":"Sanbalat","role":"Adversario de la reconstrucción.","title":"Una voz importante del relato","text":"Se burló de los trabajadores e intentó detener la obra.","why":"La oposición externa no impidió que el pueblo continuara.","reference":"Nehemías 4:1-3,7-8","gender":"m","style":"adult","mode":"historico","keyScene":false},{"stage":"05 · EL PUNTO DECISIVO","name":"Sanbalat y Tobías","role":"Opositores a la reconstrucción.","mode":"historico","title":"Resistencia y vigilancia","text":"Los enemigos trataron de intimidar y detener la reconstrucción; el pueblo tuvo que mantenerse alerta mientras trabajaba.","why":"La oposición requirió tanto valor como organización.","reference":"Nehemías 2:11–18; 3:1–32; 6:15","index":4,"keyScene":true,"after":4},{"index":10,"after":4,"name":"Tobías","role":"Adversario aliado de Sanbalat.","title":"Una voz importante del relato","text":"Participó en burlas y amenazas contra la muralla.","why":"La vigilancia fue parte de la organización de la obra.","reference":"Nehemías 4:3,7-8","gender":"m","style":"adult","mode":"historico","keyScene":false},{"stage":"06 · LAS CONSECUENCIAS","name":"Nehemías","role":"Copero del rey persa que dirigió la reconstrucción de la muralla de Jerusalén.","mode":"historico","title":"La muralla se completa","text":"La reconstrucción terminó en 52 días, causando sorpresa entre quienes se oponían.","why":"El resultado fue fruto de fe, trabajo coordinado y perseverancia.","reference":"Nehemías 2:11–18; 3:1–32; 6:15","index":5,"keyScene":true,"after":5},{"index":11,"after":5,"name":"Trabajadores de Jerusalén","role":"Familias y oficios que colaboraron.","title":"Una voz importante del relato","text":"Repararon tramos específicos mientras otros vigilaban.","why":"La obra se completó gracias a un esfuerzo coordinado.","reference":"Nehemías 3; 6:15","gender":"g","style":"group","mode":"historico","keyScene":false}],"maria":[{"stage":"01 · EL CONTEXTO","name":"María","role":"Joven de Nazaret elegida para ser la madre de Jesús.","mode":"historico","title":"Una joven en Nazaret","text":"María vivía en Nazaret y estaba comprometida para casarse con José.","why":"Su vida cotidiana cambió de forma inesperada.","reference":"Lucas 1:26–38","index":0,"keyScene":true,"after":0},{"index":6,"after":0,"name":"José, prometido de María","role":"Carpintero descendiente de David.","title":"Una voz importante del relato","text":"Estaba comprometido con María cuando ella recibió el anuncio.","why":"Su relación familiar importa para los acontecimientos del nacimiento de Jesús.","reference":"Mateo 1:18-25","gender":"m","style":"young","mode":"historico","keyScene":false},{"stage":"02 · EL PRIMER CAMBIO","name":"Gabriel","role":"Ángel que comunicó a María una noticia extraordinaria.","mode":"historico","title":"La visita de Gabriel","text":"El ángel Gabriel la saludó y le anunció que tendría un hijo llamado Jesús.","why":"Se le comunicó una responsabilidad extraordinaria.","reference":"Lucas 1:26–38","index":1,"keyScene":true,"after":1},{"index":7,"after":1,"name":"Gabriel","role":"Ángel enviado con un anuncio.","title":"Una voz importante del relato","text":"Explicó a María que tendría un hijo llamado Jesús.","why":"Su mensaje fue el punto de partida de la misión que María aceptó.","reference":"Lucas 1:26-33","gender":"g","style":"angel","mode":"historico","keyScene":false},{"stage":"03 · EL DESAFÍO","name":"María","role":"Joven de Nazaret elegida para ser la madre de Jesús.","mode":"historico","title":"Una pregunta sincera","text":"María preguntó cómo ocurriría aquello, pues todavía no había tenido relaciones con un hombre.","why":"La pregunta buscaba comprender, no rechazar el mensaje.","reference":"Lucas 1:26–38","index":2,"keyScene":true,"after":2},{"stage":"04 · LA RESPUESTA","name":"Gabriel","role":"Ángel que comunicó a María una noticia extraordinaria.","mode":"historico","title":"Una explicación y una señal","text":"Gabriel le explicó la intervención del espíritu santo y le habló de su parienta Elisabet.","why":"Recibió información que la ayudó a entender mejor la situación.","reference":"Lucas 1:26–38","index":3,"keyScene":true,"after":3},{"index":8,"after":3,"name":"Elisabet","role":"Pariente de María y madre de Juan el Bautista.","title":"Una voz importante del relato","text":"Recibió a María, y ambas compartieron su alegría por lo ocurrido.","why":"Su encuentro confirmó y fortaleció la fe de María.","reference":"Lucas 1:39-45","gender":"f","style":"older","mode":"historico","keyScene":false},{"stage":"05 · EL PUNTO DECISIVO","name":"María","role":"Joven de Nazaret elegida para ser la madre de Jesús.","mode":"historico","title":"Una respuesta de disposición","text":"María aceptó humildemente la misión que se le había comunicado.","why":"Sus palabras mostraron confianza pese a no conocer todos los detalles.","reference":"Lucas 1:26–38","index":4,"keyScene":true,"after":4},{"index":9,"after":4,"name":"Zacarías","role":"Esposo de Elisabet y sacerdote.","title":"Una voz importante del relato","text":"También había recibido un anuncio relativo al nacimiento de Juan.","why":"Los nacimientos de ambos niños están conectados en el relato de Lucas.","reference":"Lucas 1:5-25,57-66","gender":"m","style":"older","mode":"historico","keyScene":false},{"stage":"06 · LAS CONSECUENCIAS","name":"María","role":"Joven de Nazaret elegida para ser la madre de Jesús.","mode":"historico","title":"Un comienzo decisivo","text":"El relato prepara el escenario para el nacimiento de Jesús y su papel en el propósito divino.","why":"Su ejemplo une humildad, reflexión y disposición a actuar.","reference":"Lucas 1:26–38","index":5,"keyScene":true,"after":5},{"index":10,"after":5,"name":"Jesús, recién nacido","role":"Hijo de María.","title":"Una voz importante del relato","text":"Nació en Belén después de que María y José viajaran allí.","why":"Su nacimiento cumple la promesa anunciada a María.","reference":"Lucas 2:1-7","gender":"m","style":"baby","mode":"historico","keyScene":false}],"samaritano":[{"stage":"01 · EL CONTEXTO","name":"Jesús","role":"Maestro que usaba relatos y parábolas para enseñar verdades espirituales.","mode":"historico","title":"Una pregunta a Jesús","text":"Un experto en la Ley preguntó a Jesús quién debía ser considerado su prójimo. Jesús respondió con una parábola.","why":"Los personajes de la parábola ilustran una enseñanza, no están presentados como un registro de testigos históricos.","reference":"Lucas 10:25–37","index":0,"keyScene":true,"after":0},{"index":6,"after":0,"name":"Experto en la Ley","role":"Hombre que planteó la pregunta a Jesús.","title":"Una voz importante del relato","text":"Preguntó quién era su prójimo y motivó la parábola.","why":"La narración responde directamente a una cuestión ética.","reference":"Lucas 10:25-29","gender":"m","style":"adult","mode":"historico","keyScene":false},{"stage":"02 · EL PRIMER CAMBIO","name":"Viajero de la parábola","role":"Figura de una parábola de Jesús; no es una persona histórica identificada.","mode":"parabola","title":"El viajero herido","text":"En la historia, un hombre viajaba de Jerusalén a Jericó cuando unos ladrones lo atacaron y lo dejaron gravemente herido.","why":"El problema de fondo es la necesidad de alguien vulnerable.","reference":"Lucas 10:25–37","index":1,"keyScene":true,"after":1},{"index":7,"after":1,"name":"Asaltantes de la parábola","role":"Personajes de la parábola, sin nombres.","title":"Una voz importante del relato","text":"Atacaron al viajero y lo dejaron herido en el camino.","why":"La violencia crea la situación que pone a prueba la compasión.","reference":"Lucas 10:30","gender":"g","style":"group","mode":"parabola","keyScene":false},{"stage":"03 · EL DESAFÍO","name":"Sacerdote de la parábola","role":"Figura de una parábola de Jesús; no es una persona histórica identificada.","mode":"parabola","title":"Pasan sin ayudar","text":"Un sacerdote y después un levita vieron al herido, pero continuaron por el camino sin prestarle ayuda.","why":"El cargo religioso no garantizó una respuesta compasiva.","reference":"Lucas 10:25–37","index":2,"keyScene":true,"after":2},{"index":8,"after":2,"name":"Levita de la parábola","role":"Personaje sin nombre dentro del ejemplo de Jesús.","title":"Una voz importante del relato","text":"Vio al herido, pero pasó por el otro lado del camino.","why":"Se contrasta la apariencia de religiosidad con la ayuda efectiva.","reference":"Lucas 10:32","gender":"m","style":"adult","mode":"historico","keyScene":false},{"stage":"04 · LA RESPUESTA","name":"Samaritano de la parábola","role":"Figura de una parábola de Jesús que se destaca por su compasión.","mode":"parabola","title":"Un samaritano se detiene","text":"Un samaritano, de un pueblo con tensiones históricas con los judíos, sintió compasión y atendió las heridas del hombre.","why":"La ayuda vino de quien menos se esperaba.","reference":"Lucas 10:25–37","index":3,"keyScene":true,"after":3},{"index":9,"after":3,"name":"Samaritano de la parábola","role":"Personaje central del ejemplo.","title":"Una voz importante del relato","text":"Se detuvo, atendió las heridas del viajero y lo llevó a un lugar seguro.","why":"La compasión se demuestra mediante acciones concretas.","reference":"Lucas 10:33-34","gender":"m","style":"adult","mode":"historico","keyScene":false},{"stage":"05 · EL PUNTO DECISIVO","name":"Samaritano de la parábola","role":"Figura de una parábola de Jesús que se destaca por su compasión.","mode":"parabola","title":"Se ocupa de su recuperación","text":"El samaritano llevó al herido a una posada, lo cuidó y dejó dinero para que continuaran atendiéndolo.","why":"La compasión se convirtió en tiempo, esfuerzo y recursos concretos.","reference":"Lucas 10:25–37","index":4,"keyScene":true,"after":4},{"index":10,"after":4,"name":"Posadero de la parábola","role":"Persona que recibió al herido en su alojamiento.","title":"Una voz importante del relato","text":"Recibió dinero para seguir cuidando al viajero.","why":"La ayuda del samaritano también incluyó prever el cuidado posterior.","reference":"Lucas 10:35","gender":"m","style":"older","mode":"historico","keyScene":false},{"stage":"06 · LAS CONSECUENCIAS","name":"Jesús","role":"Maestro que usaba relatos y parábolas para enseñar verdades espirituales.","mode":"historico","title":"¿Quién fue el prójimo?","text":"Jesús invitó a reconocer que el prójimo fue quien actuó con misericordia.","why":"La pregunta final no es a quién limitar nuestro amor, sino cómo mostrarlo.","reference":"Lucas 10:25–37","index":5,"keyScene":true,"after":5}],"hijo":[{"stage":"01 · EL CONTEXTO","name":"Jesús","role":"Maestro que usaba relatos y parábolas para enseñar verdades espirituales.","mode":"historico","title":"Dos hijos y una herencia","text":"En una parábola de Jesús, un padre tenía dos hijos. El menor pidió anticipadamente la parte de la herencia que le correspondía.","why":"La petición inicia una historia sobre decisiones y relaciones familiares.","reference":"Lucas 15:11–32","index":0,"keyScene":true,"after":0},{"index":6,"after":0,"name":"Padre de la parábola","role":"Padre de dos hijos, sin nombre.","title":"Una voz importante del relato","text":"Accedió a darle al hijo menor la parte de la herencia que solicitó.","why":"El relato prepara el contraste entre libertad, consecuencias y amor familiar.","reference":"Lucas 15:11-12","gender":"m","style":"older","mode":"historico","keyScene":false},{"stage":"02 · EL PRIMER CAMBIO","name":"Hijo menor de la parábola","role":"Figura de la parábola del hijo que regresa; no es una persona identificada.","mode":"parabola","title":"Una salida precipitada","text":"El hijo menor viajó lejos y malgastó sus bienes viviendo irresponsablemente.","why":"La libertad que buscaba terminó acompañada de grandes pérdidas.","reference":"Lucas 15:11–32","index":1,"keyScene":true,"after":1},{"index":7,"after":1,"name":"Amigos del hijo menor","role":"Personajes ilustrativos, no identificados individualmente en el texto.","title":"Una voz importante del relato","text":"El hijo malgastó su dinero en una región lejana; la Biblia no identifica a sus acompañantes.","why":"No debe confundirse una dramatización visual con un dato del relato bíblico.","reference":"Lucas 15:13","gender":"g","style":"group","mode":"parabola","keyScene":false},{"stage":"03 · EL DESAFÍO","name":"Hijo menor de la parábola","role":"Figura de la parábola del hijo que regresa; no es una persona identificada.","mode":"parabola","title":"Necesidad y reflexión","text":"Cuando llegó el hambre, tuvo que cuidar cerdos y se vio en una situación miserable. Entonces reflexionó sobre su vida.","why":"Reconocer el error fue el comienzo del cambio.","reference":"Lucas 15:11–32","index":2,"keyScene":true,"after":2},{"index":8,"after":2,"name":"Dueño de los cerdos","role":"Ciudadano que dio trabajo al hijo menor.","title":"Una voz importante del relato","text":"Lo envió a cuidar cerdos en medio de una gran necesidad.","why":"La situación lo llevó a reflexionar sobre su conducta.","reference":"Lucas 15:14-17","gender":"m","style":"adult","mode":"historico","keyScene":false},{"stage":"04 · LA RESPUESTA","name":"Hijo menor de la parábola","role":"Figura de la parábola del hijo que regresa; no es una persona identificada.","mode":"parabola","title":"Decide regresar","text":"El joven decidió volver a su padre y admitir que había pecado, sin exigir recuperar su posición anterior.","why":"El arrepentimiento se expresó en un cambio de dirección.","reference":"Lucas 15:11–32","index":3,"keyScene":true,"after":3},{"index":9,"after":3,"name":"Trabajadores del padre","role":"Empleados mencionados por el hijo menor al recordar su hogar.","title":"Una voz importante del relato","text":"El joven recordó que ellos tenían alimento mientras él pasaba hambre.","why":"Recordar las condiciones de su casa impulsó su regreso.","reference":"Lucas 15:17-19","gender":"g","style":"group","mode":"historico","keyScene":false},{"stage":"05 · EL PUNTO DECISIVO","name":"Padre de la parábola","role":"Figura de la parábola de Jesús que muestra misericordia.","mode":"parabola","title":"Un recibimiento inesperado","text":"El padre lo vio llegar, corrió a recibirlo y celebró su retorno.","why":"La reacción del padre ilustra una misericordia llena de afecto.","reference":"Lucas 15:11–32","index":4,"keyScene":true,"after":4},{"index":10,"after":4,"name":"Siervos de la casa","role":"Personas a quienes el padre dio instrucciones.","title":"Una voz importante del relato","text":"Trajeron ropa, un anillo y prepararon una comida de celebración.","why":"La acogida fue pública y generosa.","reference":"Lucas 15:22-24","gender":"g","style":"group","mode":"historico","keyScene":false},{"stage":"06 · LAS CONSECUENCIAS","name":"Hijo mayor de la parábola","role":"Figura de la parábola del hijo que regresa; no es una persona identificada.","mode":"parabola","title":"El hermano mayor","text":"El hermano mayor se molestó por la celebración y el padre le explicó por qué era motivo de alegría recuperar a su hijo.","why":"La parábola también invita a examinar nuestra reacción cuando otros reciben perdón.","reference":"Lucas 15:11–32","index":5,"keyScene":true,"after":5}],"panes":[{"stage":"01 · EL CONTEXTO","name":"Jesús","role":"Maestro que usaba relatos y parábolas para enseñar verdades espirituales.","mode":"historico","title":"Una multitud sigue a Jesús","text":"Mucha gente acudió a escuchar a Jesús y estaba lejos de los lugares donde podía conseguir alimentos.","why":"La necesidad de la gente no pasó inadvertida para Jesús.","reference":"Juan 6:1–13","index":0,"keyScene":true,"after":0},{"index":6,"after":0,"name":"Felipe","role":"Discípulo de Jesús.","title":"Una voz importante del relato","text":"Jesús le preguntó dónde comprarían pan para toda aquella gente.","why":"Su respuesta mostró lo difícil que parecía alimentar a la multitud.","reference":"Juan 6:5-7","gender":"m","style":"adult","mode":"historico","keyScene":false},{"stage":"02 · EL PRIMER CAMBIO","name":"Andrés","role":"Discípulo de Jesús que señaló que había un muchacho con cinco panes y dos pescados.","mode":"historico","title":"Una cantidad diminuta","text":"Entre los presentes había cinco panes de cebada y dos pescados, insuficientes para una multitud tan grande.","why":"La cantidad disponible hacía evidente el problema.","reference":"Juan 6:1–13","index":1,"keyScene":true,"after":1},{"index":7,"after":1,"name":"Muchacho de los panes","role":"Joven cuyo nombre no registra el texto.","title":"Una voz importante del relato","text":"Tenía cinco panes de cebada y dos pescados.","why":"Su pequeña provisión se convirtió en punto de partida del milagro.","reference":"Juan 6:8-9","gender":"m","style":"child","mode":"historico","keyScene":false},{"stage":"03 · EL DESAFÍO","name":"Jesús","role":"Maestro que usaba relatos y parábolas para enseñar verdades espirituales.","mode":"historico","title":"Jesús da gracias","text":"Jesús organizó a la multitud, tomó el alimento y dio gracias antes de distribuirlo.","why":"El relato presenta una respuesta calmada y agradecida ante la necesidad.","reference":"Juan 6:1–13","index":2,"keyScene":true,"after":2},{"index":8,"after":2,"name":"Andrés","role":"Hermano de Pedro y discípulo de Jesús.","title":"Una voz importante del relato","text":"Informó a Jesús sobre los panes y los pescados del muchacho.","why":"Ayudó a identificar lo poco que había disponible.","reference":"Juan 6:8-9","gender":"m","style":"adult","mode":"historico","keyScene":false},{"stage":"04 · LA RESPUESTA","name":"Muchacho con panes","role":"Joven anónimo que llevaba cinco panes y dos pescados.","mode":"historico","title":"Todos reciben comida","text":"El alimento se repartió y los presentes pudieron comer hasta quedar satisfechos.","why":"La intervención de Jesús atendió una necesidad concreta de las personas.","reference":"Juan 6:1–13","index":3,"keyScene":true,"after":3},{"index":9,"after":3,"name":"Multitud reunida","role":"Grupo de miles de personas.","title":"Una voz importante del relato","text":"Se sentaron en la hierba y recibieron alimento.","why":"El milagro benefició a una gran cantidad de gente.","reference":"Juan 6:10-11","gender":"g","style":"group","mode":"historico","keyScene":false},{"stage":"05 · EL PUNTO DECISIVO","name":"Jesús","role":"Maestro que usaba relatos y parábolas para enseñar verdades espirituales.","mode":"historico","title":"Recogen las sobras","text":"Después, Jesús indicó que recogieran los pedazos que quedaban para que nada se desperdiciara.","why":"La abundancia no eliminó la importancia de evitar el desperdicio.","reference":"Juan 6:1–13","index":4,"keyScene":true,"after":4},{"index":10,"after":4,"name":"Discípulos que recogieron las sobras","role":"Discípulos de Jesús, intervención colectiva.","title":"Una voz importante del relato","text":"Recogieron doce canastas con los pedazos restantes.","why":"Jesús también enseñó a valorar y no desperdiciar alimento.","reference":"Juan 6:12-13","gender":"g","style":"group","mode":"historico","keyScene":false},{"stage":"06 · LAS CONSECUENCIAS","name":"Discípulos","role":"Seguidores de Jesús que recogieron las sobras.","mode":"historico","title":"Doce canastas","text":"Se reunieron doce canastas con los restos de los panes, una señal de la magnitud del milagro.","why":"El relato destaca tanto la generosidad como el buen uso de los recursos.","reference":"Juan 6:1–13","index":5,"keyScene":true,"after":5}],"pedro":[{"stage":"01 · EL CONTEXTO","name":"Pedro","role":"Apóstol de Jesús que aprendió del perdón después de negarlo.","mode":"historico","title":"Una noche de miedo","text":"La noche en que arrestaron a Jesús, Pedro lo siguió hasta el patio de la casa del sumo sacerdote.","why":"Su deseo de estar cerca de Jesús convivía con el temor al peligro.","reference":"Lucas 22:54–62; Juan 21:15–17","index":0,"keyScene":true,"after":0},{"index":6,"after":0,"name":"Sirvienta del patio","role":"Mujer sin nombre registrado.","title":"Una voz importante del relato","text":"Reconoció a Pedro como uno de los seguidores de Jesús.","why":"Su pregunta inició la primera negación de Pedro.","reference":"Lucas 22:56-57","gender":"f","style":"young","mode":"historico","keyScene":false},{"stage":"02 · EL PRIMER CAMBIO","name":"Pedro","role":"Apóstol de Jesús que aprendió del perdón después de negarlo.","mode":"historico","title":"Primera negación","text":"Una sirvienta identificó a Pedro como seguidor de Jesús, pero él negó conocerlo.","why":"El miedo empezó a influir en sus palabras.","reference":"Lucas 22:54–62; Juan 21:15–17","index":1,"keyScene":true,"after":1},{"index":7,"after":1,"name":"Otro testigo del patio","role":"Persona que identificó a Pedro.","title":"Una voz importante del relato","text":"Una segunda acusación hizo que Pedro negara conocer a Jesús de nuevo.","why":"El miedo de Pedro aumentó con la presión pública.","reference":"Lucas 22:58","gender":"m","style":"adult","mode":"historico","keyScene":false},{"stage":"03 · EL DESAFÍO","name":"Pedro","role":"Apóstol de Jesús que aprendió del perdón después de negarlo.","mode":"historico","title":"La negación se repite","text":"Pedro negó conocer a Jesús otras dos veces y terminó oyendo cantar al gallo.","why":"La presión lo llevó a actuar de un modo contrario a sus intenciones.","reference":"Lucas 22:54–62; Juan 21:15–17","index":2,"keyScene":true,"after":2},{"index":8,"after":2,"name":"Pariente de Malco","role":"Un pariente de un hombre herido durante el arresto de Jesús.","title":"Una voz importante del relato","text":"Afirmó que había visto a Pedro en el jardín.","why":"Su intervención precedió a una nueva negación.","reference":"Juan 18:26-27","gender":"m","style":"adult","mode":"historico","keyScene":false},{"stage":"04 · LA RESPUESTA","name":"Pedro","role":"Apóstol de Jesús que aprendió del perdón después de negarlo.","mode":"historico","title":"Reconoce su error","text":"Pedro recordó lo que Jesús le había advertido y lloró amargamente.","why":"La tristeza sincera mostró que no le era indiferente lo ocurrido.","reference":"Lucas 22:54–62; Juan 21:15–17","index":3,"keyScene":true,"after":3},{"index":9,"after":3,"name":"Jesús","role":"Maestro de Pedro.","title":"Una voz importante del relato","text":"Pedro recordó que Jesús había predicho sus tres negaciones.","why":"Aquella advertencia lo llevó a reconocer su error.","reference":"Lucas 22:61-62","gender":"m","style":"adult","mode":"historico","keyScene":false},{"stage":"05 · EL PUNTO DECISIVO","name":"Jesús","role":"Maestro que usaba relatos y parábolas para enseñar verdades espirituales.","mode":"historico","title":"Un encuentro después","text":"Después de su resurrección, Jesús habló con Pedro y le preguntó repetidamente si lo amaba.","why":"La conversación le permitió reafirmar su amor.","reference":"Lucas 22:54–62; Juan 21:15–17","index":4,"keyScene":true,"after":4},{"index":10,"after":4,"name":"Juan","role":"Discípulo de Jesús.","title":"Una voz importante del relato","text":"Estuvo presente cuando Jesús se manifestó a sus discípulos cerca del mar de Tiberíades.","why":"El ambiente prepara la conversación posterior entre Jesús y Pedro.","reference":"Juan 21:1-14","gender":"m","style":"young","mode":"historico","keyScene":false},{"stage":"06 · LAS CONSECUENCIAS","name":"Pedro","role":"Apóstol de Jesús que aprendió del perdón después de negarlo.","mode":"historico","title":"Una responsabilidad renovada","text":"Jesús encomendó a Pedro alimentar y cuidar a sus ovejas.","why":"Su error no tuvo por qué definir el resto de su vida.","reference":"Lucas 22:54–62; Juan 21:15–17","index":5,"keyScene":true,"after":5}],"dorcas":[{"stage":"01 · EL CONTEXTO","name":"Dorcas / Tabita","role":"Discípula de Jope conocida por ayudar a las viudas y hacer buenas obras.","mode":"historico","title":"Una discípula generosa","text":"Dorcas, llamada también Tabita, vivía en Jope y era conocida por las buenas obras y la ayuda que prestaba.","why":"Su fe se notaba en cómo trataba a personas necesitadas.","reference":"Hechos 9:36–42","index":0,"keyScene":true,"after":0},{"index":6,"after":0,"name":"Viudas de Jope","role":"Mujeres que habían recibido ayuda de Dorcas.","title":"Una voz importante del relato","text":"Mostraron a Pedro prendas que Dorcas les había hecho.","why":"Su tristeza revela el efecto concreto de la generosidad de Dorcas.","reference":"Hechos 9:39","gender":"f","style":"group","mode":"historico","keyScene":false},{"stage":"02 · EL PRIMER CAMBIO","name":"Discípulos de Jope","role":"Grupo que llamó a Pedro cuando murió Dorcas.","mode":"historico","title":"Dorcas enferma","text":"Dorcas enfermó y murió. La comunidad quedó profundamente triste.","why":"Su ausencia mostró cuánto había significado para otros.","reference":"Hechos 9:36–42","index":1,"keyScene":true,"after":1},{"index":7,"after":1,"name":"Dos mensajeros de Jope","role":"Hombres enviados a buscar a Pedro.","title":"Una voz importante del relato","text":"Viajaron hasta donde estaba Pedro y le pidieron que acudiera.","why":"Su iniciativa conectó a la congregación con Pedro.","reference":"Hechos 9:38","gender":"g","style":"group","mode":"historico","keyScene":false},{"stage":"03 · EL DESAFÍO","name":"Viuda de Jope","role":"Una de las viudas del relato; las Escrituras no conservan su nombre.","mode":"historico","title":"Las viudas recuerdan","text":"Cuando llegó Pedro, varias viudas le mostraron prendas que Dorcas había confeccionado mientras estaba con ellas.","why":"Las prendas eran pruebas tangibles de su bondad.","reference":"Hechos 9:36–42","index":2,"keyScene":true,"after":2},{"index":8,"after":2,"name":"Pedro","role":"Apóstol de Jesús.","title":"Una voz importante del relato","text":"Llegó a la habitación donde estaba Dorcas y escuchó a las viudas.","why":"Fue testigo de la profunda pérdida que sentía la comunidad.","reference":"Hechos 9:39","gender":"m","style":"adult","mode":"historico","keyScene":false},{"stage":"04 · LA RESPUESTA","name":"Pedro","role":"Apóstol de Jesús que aprendió del perdón después de negarlo.","mode":"historico","title":"Pedro entra y ora","text":"Pedro pidió que los demás salieran de la habitación y se arrodilló a orar.","why":"La escena presenta un momento solemne de dependencia de Dios.","reference":"Hechos 9:36–42","index":3,"keyScene":true,"after":3},{"index":9,"after":3,"name":"Discípulos de Jope","role":"Miembros de la congregación local.","title":"Una voz importante del relato","text":"Prepararon el cuerpo de Dorcas y pidieron ayuda a Pedro.","why":"El relato muestra apoyo mutuo en la congregación.","reference":"Hechos 9:36-38","gender":"g","style":"group","mode":"historico","keyScene":false},{"stage":"05 · EL PUNTO DECISIVO","name":"Pedro","role":"Apóstol de Jesús que aprendió del perdón después de negarlo.","mode":"historico","title":"Tabita vuelve a vivir","text":"Pedro se dirigió a Dorcas y ella abrió los ojos. Después la ayudó a levantarse.","why":"La noticia transformó el duelo en alegría.","reference":"Hechos 9:36–42","index":4,"keyScene":true,"after":4},{"stage":"06 · LAS CONSECUENCIAS","name":"Creyentes de Jope","role":"Grupo que conoció el milagro y se fortaleció.","mode":"historico","title":"Muchos se enteran","text":"La resurrección se conoció por toda Jope y muchas personas llegaron a creer.","why":"El final resalta tanto el milagro como la vida generosa que Dorcas había llevado.","reference":"Hechos 9:36–42","index":5,"keyScene":true,"after":5},{"index":10,"after":5,"name":"Creyentes de Jope","role":"Personas que conocieron el suceso.","title":"Una voz importante del relato","text":"Muchos oyeron la noticia de que Dorcas había vuelto a vivir.","why":"El acontecimiento fortaleció la fe de la comunidad.","reference":"Hechos 9:42","gender":"g","style":"group","mode":"historico","keyScene":false}],"lidia":[{"stage":"01 · EL CONTEXTO","name":"Lidia","role":"Comerciante de púrpura que escuchó a Pablo en Filipos.","mode":"historico","title":"Una comerciante en Filipos","text":"Lidia era vendedora de púrpura, originaria de Tiatira, y se encontraba en Filipos.","why":"Su oficio y su presencia en la ciudad forman parte del contexto del relato.","reference":"Hechos 16:11–15, 40","index":0,"keyScene":true,"after":0},{"index":6,"after":0,"name":"Mujeres que oraban junto al río","role":"Grupo reunido para orar cerca de Filipos.","title":"Una voz importante del relato","text":"Pablo habló con ellas en un lugar de oración.","why":"El comienzo de la historia de Lidia tiene lugar fuera de una sinagoga.","reference":"Hechos 16:13","gender":"f","style":"group","mode":"historico","keyScene":false},{"stage":"02 · EL PRIMER CAMBIO","name":"Pablo","role":"Apóstol que anunció el mensaje cristiano en Filipos.","mode":"historico","title":"Una reunión junto al río","text":"Pablo y sus compañeros fueron a un lugar fuera de la puerta de la ciudad donde se reunían mujeres para orar.","why":"Allí comenzaron a conversar sobre el mensaje cristiano.","reference":"Hechos 16:11–15, 40","index":1,"keyScene":true,"after":1},{"index":7,"after":1,"name":"Silas","role":"Compañero de viaje de Pablo.","title":"Una voz importante del relato","text":"Acompañó la predicación en Filipos.","why":"Su presencia forma parte de la misión que llegó a la ciudad.","reference":"Hechos 16:11-15,19","gender":"m","style":"adult","mode":"historico","keyScene":false},{"stage":"03 · EL DESAFÍO","name":"Lidia","role":"Comerciante de púrpura que escuchó a Pablo en Filipos.","mode":"historico","title":"Lidia escucha con atención","text":"Lidia prestó atención a lo que Pablo explicó, y el relato dice que Jehová abrió su corazón para responder.","why":"La escucha atenta fue el primer paso de su respuesta.","reference":"Hechos 16:11–15, 40","index":2,"keyScene":true,"after":2},{"index":8,"after":2,"name":"Timoteo","role":"Colaborador de Pablo.","title":"Una voz importante del relato","text":"Viajó con el grupo durante parte de esta expedición misionera.","why":"Ayuda a ubicar a Lidia dentro del comienzo de la predicación en Macedonia.","reference":"Hechos 16:1-12","gender":"m","style":"young","mode":"historico","keyScene":false},{"stage":"04 · LA RESPUESTA","name":"Lidia","role":"Comerciante de púrpura que escuchó a Pablo en Filipos.","mode":"historico","title":"Una decisión pública","text":"Lidia y los de su casa se bautizaron.","why":"La decisión mostró que lo que había escuchado tenía consecuencias para su vida.","reference":"Hechos 16:11–15, 40","index":3,"keyScene":true,"after":3},{"index":9,"after":3,"name":"Casa de Lidia","role":"Personas de su hogar; nombres no registrados.","title":"Una voz importante del relato","text":"Junto con Lidia recibieron el bautismo.","why":"La decisión de Lidia tuvo repercusiones familiares.","reference":"Hechos 16:14-15","gender":"g","style":"group","mode":"historico","keyScene":false},{"stage":"05 · EL PUNTO DECISIVO","name":"Lidia","role":"Comerciante de púrpura que escuchó a Pablo en Filipos.","mode":"historico","title":"Ofrece alojamiento","text":"Lidia invitó insistentemente a Pablo y a sus compañeros a quedarse en su casa.","why":"Su hospitalidad ayudó a quienes estaban enseñando en Filipos.","reference":"Hechos 16:11–15, 40","index":4,"keyScene":true,"after":4},{"index":10,"after":4,"name":"Carcelero de Filipos","role":"Funcionario mencionado más adelante en la estancia de Pablo.","title":"Una voz importante del relato","text":"Preguntó cómo salvarse y él y los suyos fueron bautizados.","why":"Su historia ocurre en la misma visita que inició la congregación en Filipos.","reference":"Hechos 16:25-34","gender":"m","style":"adult","mode":"historico","keyScene":false},{"stage":"06 · LAS CONSECUENCIAS","name":"Pablo","role":"Apóstol que anunció el mensaje cristiano en Filipos.","mode":"historico","title":"Una casa abierta","text":"Después de salir de prisión, Pablo y Silas se reunieron con los hermanos en casa de Lidia antes de continuar su viaje.","why":"Su hogar se convirtió en un lugar de apoyo para otros.","reference":"Hechos 16:11–15, 40","index":5,"keyScene":true,"after":5}]};
